import {b, type ReviewedLesson} from './types';

const reviewed: Record<string,ReviewedLesson> = {
  'm2-w034-e1': {
    application:b('Independence factors the joint law into marginal probabilities, making product expectations and event probabilities directly computable.','Tính độc lập phân tích luật chung thành tích các xác suất biên, giúp tính trực tiếp xác suất biến cố và kỳ vọng tích.'),
    formula:b(String.raw`$E[g(X,Y)]=\sum_{x,y}g(x,y)P_X(x)P_Y(y)\quad(X,Y\text{ independent discrete};\ E|g(X,Y)|<\infty).$`,String.raw`$E[g(X,Y)]=\sum_{x,y}g(x,y)P_X(x)P_Y(y)\quad(X,Y\text{ rời rạc độc lập};\ E|g(X,Y)|<\infty).$`),
    steps:[b(String.raw`For independent Bernoulli(1/2) variables, each pair $(0,0),(1,0),(0,1),(1,1)$ has probability $1/4$.`,String.raw`Với hai biến Bernoulli(1/2) độc lập, mỗi cặp $(0,0),(1,0),(0,1),(1,1)$ có xác suất $1/4$.`),b(String.raw`Exactly one success occurs in two of the four pairs, so $P(X+Y=1)=1/2$; only $(1,1)$ contributes to $E[XY]=1/4$.`,String.raw`Đúng một lần thành công ở hai trong bốn cặp, nên $P(X+Y=1)=1/2$; chỉ $(1,1)$ đóng góp vào $E[XY]=1/4$.`),b(String.raw`Since $(X+Y)^2=X+Y+2XY$, its mean is $1/2+1/2+2(1/4)=3/2$; direct sum gives $(0+1+1+4)/4=3/2$.`,String.raw`Vì $(X+Y)^2=X+Y+2XY$, kỳ vọng là $1/2+1/2+2(1/4)=3/2$; cộng trực tiếp cho $(0+1+1+4)/4=3/2$.`)],
    primarySolution:[b(String.raw`Independence makes the four Bernoulli pairs equiprobable. The two mixed pairs give $P(X+Y=1)=2/4=1/2$.`,String.raw`Tính độc lập khiến bốn cặp Bernoulli đồng xác suất. Hai cặp hỗn hợp cho $P(X+Y=1)=2/4=1/2$.`),b(String.raw`Only the $(1,1)$ pair has $XY=1$, so $E[XY]=1/4$.`,String.raw`Chỉ cặp $(1,1)$ có $XY=1$, nên $E[XY]=1/4$.`),b(String.raw`Use $(X+Y)^2=X+Y+2XY$: $E=1/2+1/2+1/2=3/2$. The pointwise four-value check is $(0+1+1+4)/4=3/2$.`,String.raw`Dùng $(X+Y)^2=X+Y+2XY$: $E=1/2+1/2+1/2=3/2$. Kiểm tra bốn giá trị từng điểm cho $(0+1+1+4)/4=3/2$.`)],
    companions:[
      {prompt:b(String.raw`Independent Bernoulli variables have success probabilities $P(X=1)=0.3$ and $P(Y=1)=0.6$. Find $P(X+Y=1)$, $E[XY]$, and $E[(X+Y)^2]$.`,String.raw`Hai biến Bernoulli độc lập có xác suất thành công $P(X=1)=0.3$, $P(Y=1)=0.6$. Tính $P(X+Y=1)$, $E[XY]$ và $E[(X+Y)^2]$.`),solution:[b(String.raw`Exactly one success has probability $0.3(0.4)+0.7(0.6)=0.54$.`,String.raw`Đúng một lần thành công có xác suất $0.3(0.4)+0.7(0.6)=0.54$.`),b(String.raw`Independence gives $E[XY]=E[X]E[Y]=0.3(0.6)=0.18$.`,String.raw`Độc lập cho $E[XY]=E[X]E[Y]=0.3(0.6)=0.18$.`),b(String.raw`The square mean is $E[X]+E[Y]+2E[XY]=0.3+0.6+0.36=1.26$.`,String.raw`Kỳ vọng bình phương tổng là $E[X]+E[Y]+2E[XY]=0.3+0.6+0.36=1.26$.`)]},
      {prompt:b(String.raw`Independent Bernoulli variables have parameters $1/5$ and $1/2$. Compute the probability of exactly one success, their product mean, and the squared-sum mean.`,String.raw`Hai biến Bernoulli độc lập có tham số $1/5$ và $1/2$. Tính xác suất đúng một lần thành công, kỳ vọng tích và kỳ vọng bình phương tổng.`),solution:[b(String.raw`The mixed outcomes have total probability $(1/5)(1/2)+(4/5)(1/2)=1/2$.`,String.raw`Hai kết quả hỗn hợp có tổng xác suất $(1/5)(1/2)+(4/5)(1/2)=1/2$.`),b(String.raw`The product is one only when both succeed, so $E[XY]=(1/5)(1/2)=1/10$.`,String.raw`Tích bằng một chỉ khi cả hai thành công, nên $E[XY]=(1/5)(1/2)=1/10$.`),b(String.raw`$E[(X+Y)^2]=1/5+1/2+2/10=9/10$.`,String.raw`$E[(X+Y)^2]=1/5+1/2+2/10=9/10$.`)]},
      {prompt:b(String.raw`Independent variables satisfy $P(X=2)=1/3$ (otherwise 0) and $P(Y=3)=1/4$ (otherwise 1). Find $P(X+Y=5)$ and $E[XY]$.`,String.raw`Hai biến độc lập thỏa $P(X=2)=1/3$ (còn lại bằng 0) và $P(Y=3)=1/4$ (còn lại bằng 1). Tính $P(X+Y=5)$ và $E[XY]$.`),solution:[b(String.raw`The sum is 5 only for $X=2,Y=3$, whose product-law probability is $(1/3)(1/4)=1/12$.`,String.raw`Tổng bằng 5 chỉ khi $X=2,Y=3$, có xác suất theo luật tích $(1/3)(1/4)=1/12$.`),b(String.raw`$E[X]=2/3$ and $E[Y]=3(1/4)+1(3/4)=3/2$.`,String.raw`$E[X]=2/3$ và $E[Y]=3(1/4)+1(3/4)=3/2$.`),b(String.raw`By independence, $E[XY]=E[X]E[Y]=(2/3)(3/2)=1$.`,String.raw`Do độc lập, $E[XY]=E[X]E[Y]=(2/3)(3/2)=1$.`)]}
    ],
    reviewNote:'The four-point Bernoulli law factors only because independence is given. All primary payoffs are bounded, so the expectation identity is finite.',
    sourceIds:['p-mit18175']
  },
  'm2-w034-e2': {
    application:b('A finite sum of event probabilities bounds the chance of any occurrence far enough out, with no independence assumption.','Tổng xác suất biến cố hữu hạn chặn khả năng có lần xảy ra ở đủ xa, không cần giả định độc lập.'),
    formula:b(String.raw`$\sum_{n\ge1}P(A_n)<\infty\quad\Longrightarrow\quad P(A_n\ \mathrm{i.o.})=0,\quad A_n\ \mathrm{i.o.}:=\bigcap_{m\ge1}\bigcup_{n\ge m}A_n.$`,String.raw`$\sum_{n\ge1}P(A_n)<\infty\quad\Longrightarrow\quad P(A_n\ \mathrm{i.o.})=0,\quad A_n\ \mathrm{i.o.}:=\bigcap_{m\ge1}\bigcup_{n\ge m}A_n.$`),
    steps:[b(String.raw`Define tail unions $B_m=\bigcup_{n\ge m}A_n$; they decrease and their intersection is the event of infinitely many occurrences.`,String.raw`Định nghĩa hợp đuôi $B_m=\bigcup_{n\ge m}A_n$; chúng giảm và giao là biến cố xảy ra vô hạn lần.`),b(String.raw`The union bound gives $P(B_m)\le\sum_{n\ge m}P(A_n)$, and summability makes this tail tend to zero.`,String.raw`Chặn hợp cho $P(B_m)\le\sum_{n\ge m}P(A_n)$; tính khả tổng khiến đuôi này tiến về không.`),b(String.raw`Continuity from above yields $P(\cap_mB_m)=\lim_mP(B_m)=0$. No independence was used.`,String.raw`Tính liên tục từ trên cho $P(\cap_mB_m)=\lim_mP(B_m)=0$. Không dùng tính độc lập.`)],
    primarySolution:[b(String.raw`Let $B_m=\bigcup_{n\ge m}A_n$. Then $B_m\downarrow$ and $\bigcap_mB_m=A_n\ \mathrm{i.o.}$.`,String.raw`Đặt $B_m=\bigcup_{n\ge m}A_n$. Khi đó $B_m\downarrow$ và $\bigcap_mB_m=A_n\ \mathrm{i.o.}$.`),b(String.raw`By the union bound, $P(B_m)\le\sum_{n\ge m}P(A_n)\to0$.`,String.raw`Theo chặn hợp, $P(B_m)\le\sum_{n\ge m}P(A_n)\to0$.`),b(String.raw`Continuity from above gives $P(A_n\ \mathrm{i.o.})=\lim_mP(B_m)=0$. Independence is unnecessary.`,String.raw`Tính liên tục từ trên cho $P(A_n\ \mathrm{i.o.})=\lim_mP(B_m)=0$. Không cần độc lập.`)],
    companions:[
      {prompt:b(String.raw`Suppose $P(A_n)=3^{-n}$ for n>=1. Bound $P(A_n\ \mathrm{i.o.})$ using the tail from m onward.`,String.raw`Giả sử $P(A_n)=3^{-n}$ với n>=1. Chặn $P(A_n\ \mathrm{i.o.})$ bằng đuôi từ m trở đi.`),solution:[b(String.raw`For $B_m=\cup_{n\ge m}A_n$, the union bound gives $P(B_m)\le\sum_{n\ge m}3^{-n}$.`,String.raw`Với $B_m=\cup_{n\ge m}A_n$, chặn hợp cho $P(B_m)\le\sum_{n\ge m}3^{-n}$.`),b(String.raw`The geometric tail is $(1/2)3^{1-m}$, which tends to zero.`,String.raw`Đuôi hình học bằng $(1/2)3^{1-m}$, tiến về không.`),b(String.raw`Since the i.o. event lies in every B_m, its probability is zero.`,String.raw`Vì biến cố i.o. nằm trong mọi B_m, xác suất của nó bằng không.`)]},
      {prompt:b(String.raw`For U uniform on [0,1], set $C_n=[0,1/n^2]$. Use Borel–Cantelli I to decide whether U belongs to infinitely many C_n.`,String.raw`Với U đều trên [0,1], đặt $C_n=[0,1/n^2]$. Dùng Borel–Cantelli I quyết định U có thuộc vô hạn C_n hay không.`),solution:[b(String.raw`$P(U\in C_n)=1/n^2$ and $\sum_n1/n^2<\infty$.`,String.raw`$P(U\in C_n)=1/n^2$ và $\sum_n1/n^2<\infty$.`),b(String.raw`Borel–Cantelli I applies without independence and says $P(C_n\ \mathrm{i.o.})=0$.`,String.raw`Borel–Cantelli I áp dụng không cần độc lập và cho $P(C_n\ \mathrm{i.o.})=0$.`),b(String.raw`Indeed every fixed U>0 is eventually larger than $1/n^2$; only U=0 can occur infinitely, a null point.`,String.raw`Thật vậy, mọi U>0 cố định cuối cùng lớn hơn $1/n^2$; chỉ U=0 có thể thuộc vô hạn lần, nhưng đó là điểm không.`)]},
      {prompt:b(String.raw`Events have probabilities $P(D_n)=2^{-n-1}$. Show that only finitely many D_n occur almost surely, regardless of dependence.`,String.raw`Các biến cố có xác suất $P(D_n)=2^{-n-1}$. Chứng minh chỉ hữu hạn D_n xảy ra hầu chắc chắn, bất kể phụ thuộc thế nào.`),solution:[b(String.raw`The probability series is geometric: $\sum_{n\ge1}2^{-n-1}=1/2<\infty$.`,String.raw`Chuỗi xác suất hình học: $\sum_{n\ge1}2^{-n-1}=1/2<\infty$.`),b(String.raw`The first Borel–Cantelli lemma applies because it assumes only summability.`,String.raw`Bổ đề Borel–Cantelli thứ nhất áp dụng vì chỉ cần tính khả tổng.`),b(String.raw`It gives $P(D_n\ \mathrm{i.o.})=0$, so the number of occurrences is finite almost surely.`,String.raw`Bổ đề cho $P(D_n\ \mathrm{i.o.})=0$, nên số lần xảy ra hữu hạn hầu chắc chắn.`)]}
    ],
    reviewNote:'Tail unions decrease to the i.o. event; finite probability measure gives continuity from above. The first Borel–Cantelli conclusion needs no independence.',
    sourceIds:['p-mit18175']
  },
  'm2-w034-e3': {
    application:b('Independence factors finite probabilities of avoiding events; a divergent probability sum forces those products to vanish.','Tính độc lập phân tích xác suất tránh biến cố thành tích hữu hạn; tổng xác suất phân kỳ khiến các tích đó triệt tiêu.'),
    formula:b(String.raw`$\text{events }A_n\text{ independent},\ \sum_nP(A_n)=\infty\quad\Longrightarrow\quad P(A_n\ \mathrm{i.o.})=1.$`,String.raw`$\text{các biến cố }A_n\text{ độc lập},\ \sum_nP(A_n)=\infty\quad\Longrightarrow\quad P(A_n\ \mathrm{i.o.})=1.$`),
    steps:[b(String.raw`For fixed m<=N, independence gives $P(\cap_{n=m}^NA_n^c)=\prod_{n=m}^N(1-p_n)$, where $p_n=P(A_n)$.`,String.raw`Với m<=N cố định, độc lập cho $P(\cap_{n=m}^NA_n^c)=\prod_{n=m}^N(1-p_n)$, với $p_n=P(A_n)$.`),b(String.raw`Since $1-u\le e^{-u}$ for u in [0,1], this is at most $\exp(-\sum_{n=m}^Np_n)\to0$.`,String.raw`Vì $1-u\le e^{-u}$ với u trong [0,1], tích không vượt $\exp(-\sum_{n=m}^Np_n)\to0$.`),b(String.raw`Let N increase: the no-occurrence tail has probability zero. Thus each tail union has probability one, and their countable intersection (i.o.) has probability one.`,String.raw`Cho N tăng: biến cố không có lần xảy ra trong đuôi có xác suất không. Mỗi hợp đuôi vì thế có xác suất một, nên giao đếm được (i.o.) cũng xác suất một.`)],
    primarySolution:[b(String.raw`Fix m. Independence factors the finite avoidance event: $P(\cap_{n=m}^NA_n^c)=\prod_{n=m}^N(1-p_n)$.`,String.raw`Cố định m. Tính độc lập phân tích biến cố tránh hữu hạn: $P(\cap_{n=m}^NA_n^c)=\prod_{n=m}^N(1-p_n)$.`),b(String.raw`Use $1-p_n\le e^{-p_n}$ to bound it by $\exp(-\sum_{n=m}^Np_n)$, which tends to zero as N grows.`,String.raw`Dùng $1-p_n\le e^{-p_n}$ chặn bởi $\exp(-\sum_{n=m}^Np_n)$, tiến về không khi N tăng.`),b(String.raw`Continuity from above gives $P(\cap_{n\ge m}A_n^c)=0$, hence $P(\cup_{n\ge m}A_n)=1$.`,String.raw`Tính liên tục từ trên cho $P(\cap_{n\ge m}A_n^c)=0$, nên $P(\cup_{n\ge m}A_n)=1$.`),b(String.raw`Intersect these probability-one tail unions over m; the result is $A_n$ infinitely often with probability one. Independence enters only in the finite-product identity.`,String.raw`Giao các hợp đuôi xác suất một theo m được biến cố $A_n$ xảy ra vô hạn lần với xác suất một. Độc lập chỉ dùng ở đẳng thức tích hữu hạn.`)],
    companions:[
      {prompt:b(String.raw`Independent trials have event probability $P(A_n)=1/3$ at every n. Find the probability of infinitely many occurrences.`,String.raw`Các phép thử độc lập có xác suất biến cố $P(A_n)=1/3$ ở mọi n. Tìm xác suất xảy ra vô hạn lần.`),solution:[b(String.raw`The sum $\sum_nP(A_n)=\sum_n1/3$ diverges.`,String.raw`Tổng $\sum_nP(A_n)=\sum_n1/3$ phân kỳ.`),b(String.raw`For any fixed m, the chance of no occurrence from m through N is $(2/3)^{N-m+1}\to0$.`,String.raw`Với m cố định, xác suất không xảy ra từ m đến N là $(2/3)^{N-m+1}\to0$.`),b(String.raw`Each tail has an occurrence with probability one; intersecting over m gives $P(A_n\ \mathrm{i.o.})=1$.`,String.raw`Mỗi đuôi có biến cố xảy ra với xác suất một; giao theo m cho $P(A_n\ \mathrm{i.o.})=1$.`)]},
      {prompt:b(String.raw`Let independent U_n be uniform on [0,1] and $A_n=\{U_n<1/(n+1)\}$. Show infinitely many A_n occur almost surely.`,String.raw`Cho U_n độc lập đều trên [0,1] và $A_n=\{U_n<1/(n+1)\}$. Chứng minh vô hạn A_n xảy ra hầu chắc chắn.`),solution:[b(String.raw`The events are independent because each uses a distinct independent U_n.`,String.raw`Các biến cố độc lập vì mỗi biến cố dùng một U_n độc lập riêng.`),b(String.raw`Their probabilities sum to $\sum_{n\ge1}1/(n+1)=\infty$.`,String.raw`Tổng xác suất là $\sum_{n\ge1}1/(n+1)=\infty$.`),b(String.raw`The second Borel–Cantelli lemma therefore gives $P(A_n\ \mathrm{i.o.})=1$.`,String.raw`Bổ đề Borel–Cantelli thứ hai suy ra $P(A_n\ \mathrm{i.o.})=1$.`)]},
      {prompt:b(String.raw`In independent Bernoulli trials with success probability 0.01, determine whether successes occur infinitely often almost surely.`,String.raw`Trong các phép thử Bernoulli độc lập có xác suất thành công 0.01, hãy quyết định thành công có xảy ra vô hạn lần hầu chắc chắn không.`),solution:[b(String.raw`The event probabilities have divergent sum $\sum_n0.01=\infty$.`,String.raw`Tổng xác suất biến cố là $\sum_n0.01=\infty$.`),b(String.raw`Independence makes each finite no-success probability $(0.99)^{N-m+1}$, which tends to zero.`,String.raw`Độc lập khiến xác suất không thành công trong đoạn hữu hạn bằng $(0.99)^{N-m+1}$, tiến về không.`),b(String.raw`The second Borel–Cantelli conclusion is probability one for infinitely many successes.`,String.raw`Kết luận Borel–Cantelli thứ hai cho xác suất một có vô hạn lần thành công.`)]}
    ],
    reviewNote:'For each tail, independence is used to factor the finite no-event probability; 1−p≤e^(−p) and divergence force the limit to zero. Continuity from above then applies.',
    sourceIds:['p-mit18175']
  },
  'm2-w034-e4': {
    application:b('A divergent sum alone does not force repeated events: perfectly dependent events may repeat together or fail together.','Chỉ tổng phân kỳ chưa buộc biến cố lặp lại: các biến cố phụ thuộc hoàn toàn có thể cùng lặp hoặc cùng vắng mặt.'),
    formula:b(String.raw`$A_n=A,\ P(A)=1/2:\quad \sum_nP(A_n)=\infty,\qquad P(A_n\ \mathrm{i.o.})=1/2.$`,String.raw`$A_n=A,\ P(A)=1/2:\quad \sum_nP(A_n)=\infty,\qquad P(A_n\ \mathrm{i.o.})=1/2.$`),
    steps:[b(String.raw`Each event has probability $1/2$, so the partial probability sum is $N/2$ and diverges.`,String.raw`Mỗi biến cố có xác suất $1/2$, nên tổng riêng xác suất là $N/2$ và phân kỳ.`),b(String.raw`The event occurs infinitely often exactly on A: if A occurs, every A_n occurs; otherwise none occurs.`,String.raw`Biến cố xảy ra vô hạn lần đúng trên A: nếu A xảy ra thì mọi A_n xảy ra, nếu không thì không biến cố nào xảy ra.`),b(String.raw`Thus $P(A_n\ \mathrm{i.o.})=P(A)=1/2$, not one; independence fails since $P(A_n\cap A_{n+1})=1/2\ne1/4$.`,String.raw`Vậy $P(A_n\ \mathrm{i.o.})=P(A)=1/2$, không phải một; độc lập thất bại vì $P(A_n\cap A_{n+1})=1/2\ne1/4$.`)],
    primarySolution:[b(String.raw`Because $A_n=A$, $\sum_nP(A_n)=\sum_n1/2=\infty$.`,String.raw`Vì $A_n=A$, ta có $\sum_nP(A_n)=\sum_n1/2=\infty$.`),b(String.raw`The tail union $\cup_{n\ge m}A_n$ equals A for every m; intersecting the tail unions still gives A.`,String.raw`Hợp đuôi $\cup_{n\ge m}A_n$ bằng A với mọi m; giao các hợp đuôi vẫn là A.`),b(String.raw`Hence the i.o. probability is $1/2$. Independence fails because $P(A\cap A)=1/2\ne P(A)^2=1/4$, so Borel–Cantelli II does not apply.`,String.raw`Do đó xác suất i.o. bằng $1/2$. Độc lập thất bại vì $P(A\cap A)=1/2\ne P(A)^2=1/4$, nên không áp dụng Borel–Cantelli II.`)],
    companions:[
      {prompt:b(String.raw`Let U be uniform on (0,1) and $C_n=(0,1/n)$. The sum of event probabilities diverges. Compute $P(C_n\ \mathrm{i.o.})$.`,String.raw`Cho U đều trên (0,1) và $C_n=(0,1/n)$. Tổng xác suất biến cố phân kỳ. Tính $P(C_n\ \mathrm{i.o.})$.`),solution:[b(String.raw`The events decrease and $P(C_n)=1/n$, so $\sum_nP(C_n)=\infty$.`,String.raw`Các biến cố giảm và $P(C_n)=1/n$, nên $\sum_nP(C_n)=\infty$.`),b(String.raw`Their intersection is empty: no fixed U>0 is below 1/n for every n, and U=0 is excluded.`,String.raw`Giao của chúng rỗng: không U>0 cố định nào nhỏ hơn 1/n với mọi n, còn U=0 bị loại.`),b(String.raw`For a decreasing sequence, i.o. equals the intersection; therefore its probability is 0 despite the divergent sum.`,String.raw`Với dãy giảm, i.o. bằng giao; vì vậy xác suất bằng 0 dù tổng phân kỳ.`)]},
      {prompt:b(String.raw`Let A have probability 1/4 and define alternating events $D_{2k}=A$, $D_{2k-1}=A^c$. Find the probability sum and i.o. event.`,String.raw`Cho A có xác suất 1/4, định nghĩa biến cố luân phiên $D_{2k}=A$, $D_{2k-1}=A^c$. Tìm tổng xác suất và biến cố i.o.`),solution:[b(String.raw`Every even event has probability 1/4 and every odd event 3/4, so the probability series diverges.`,String.raw`Mỗi biến cố chẵn có xác suất 1/4, mỗi biến cố lẻ có xác suất 3/4, nên chuỗi xác suất phân kỳ.`),b(String.raw`On A, every even D_n occurs infinitely often; on A^c, every odd D_n occurs infinitely often.`,String.raw`Trên A, mọi D_n chẵn xảy ra vô hạn lần; trên A^c, mọi D_n lẻ xảy ra vô hạn lần.`),b(String.raw`Thus $D_n$ i.o. is the whole space and has probability 1, showing dependence can yield a different outcome.`,String.raw`Vậy biến cố $D_n$ i.o. là toàn không gian và có xác suất 1, cho thấy phụ thuộc có thể cho kết quả khác.`)]},
      {prompt:b(String.raw`On three equally likely outcomes let every $E_n=\{1\}$. Determine $\sum_nP(E_n)$ and the i.o. probability.`,String.raw`Trên ba kết quả đồng xác suất, cho mọi $E_n=\{1\}$. Xác định $\sum_nP(E_n)$ và xác suất i.o.`),solution:[b(String.raw`Each probability equals 1/3, so the infinite sum diverges.`,String.raw`Mỗi xác suất bằng 1/3 nên tổng vô hạn phân kỳ.`),b(String.raw`The i.o. event is exactly outcome 1 because it belongs to every E_n.`,String.raw`Biến cố i.o. chính là kết quả 1 vì kết quả này thuộc mọi E_n.`),b(String.raw`Therefore its probability is 1/3, and the repeated events are not independent.`,String.raw`Do đó xác suất bằng 1/3 và các biến cố lặp lại không độc lập.`)]}
    ],
    reviewNote:'This repeated-event example has divergent sum but only half probability of infinitely many occurrences. The nested-uniform companion has i.o. probability zero; both show why independence matters for the second lemma.',
    sourceIds:['p-mit18175']
  },
  'm2-w034-e5': {
    application:b('Apply the first Borel–Cantelli lemma at countably many rational error tolerances, then combine the probability-one events.','Áp dụng bổ đề Borel–Cantelli thứ nhất tại vô hạn ngưỡng sai số hữu tỷ đếm được, rồi kết hợp các biến cố xác suất một.'),
    formula:b(String.raw`$\forall q\in\mathbb Q_{>0},\ \sum_nP(|X_n-X|>q)<\infty\quad\Longrightarrow\quad X_n\to X\text{ a.s.}$`,String.raw`$\forall q\in\mathbb Q_{>0},\ \sum_nP(|X_n-X|>q)<\infty\quad\Longrightarrow\quad X_n\to X\text{ h.c.}$`),
    steps:[b(String.raw`For each rational q>0, Borel–Cantelli I says the event $|X_n-X|>q$ occurs only finitely often almost surely.`,String.raw`Với mỗi q hữu tỷ dương, Borel–Cantelli I cho biến cố $|X_n-X|>q$ chỉ xảy ra hữu hạn lần hầu chắc chắn.`),b(String.raw`Intersect the resulting probability-one sets over the countable set $\mathbb Q_{>0}$; the intersection still has probability one.`,String.raw`Giao các tập xác suất một trên tập $\mathbb Q_{>0}$ đếm được vẫn có xác suất một.`),b(String.raw`On that intersection, for any real $\varepsilon>0$ choose rational $q<\varepsilon$. Eventually $|X_n-X|\le q<\varepsilon$, which is a.s. convergence.`,String.raw`Trên giao đó, với mọi $\varepsilon>0$ thực chọn q hữu tỷ $q<\varepsilon$. Cuối cùng $|X_n-X|\le q<\varepsilon$, tức hội tụ hầu chắc.`)],
    primarySolution:[b(String.raw`For fixed rational $\varepsilon>0$, the bound $P(|X_n-X|>\varepsilon)\le2^{-n}$ is summable, so only finitely many violations occur a.s.`,String.raw`Với $\varepsilon>0$ hữu tỷ cố định, chặn $P(|X_n-X|>\varepsilon)\le2^{-n}$ có tổng hữu hạn, nên chỉ hữu hạn lần vi phạm hầu chắc.`),b(String.raw`Intersect these probability-one statements over all positive rational epsilon; countability preserves probability one.`,String.raw`Giao các mệnh đề xác suất một này trên mọi epsilon hữu tỷ dương vẫn có xác suất một vì tập chỉ số đếm được.`),b(String.raw`Given any real delta>0, choose rational epsilon<delta. Beyond its last violation, $|X_n-X|\le\varepsilon<\delta$; hence $X_n\to X$ a.s.`,String.raw`Với delta>0 thực bất kỳ, chọn epsilon hữu tỷ nhỏ hơn delta. Sau lần vi phạm cuối, $|X_n-X|\le\varepsilon<\delta$; suy ra $X_n\to X$ hầu chắc.`)],
    companions:[
      {prompt:b(String.raw`Let $X_n=1/n$ deterministically and X=0. Verify the rational-threshold summability condition and convergence.`,String.raw`Cho $X_n=1/n$ tất định và X=0. Kiểm tra điều kiện khả tổng theo ngưỡng hữu tỷ và tính hội tụ.`),solution:[b(String.raw`For fixed q>0, the event $|X_n|>q$ is empty whenever n>=1/q.`,String.raw`Với q>0 cố định, biến cố $|X_n|>q$ rỗng khi n>=1/q.`),b(String.raw`Thus only finitely many terms in $\sum_nP(|X_n|>q)$ are nonzero, so the sum is finite.`,String.raw`Vì vậy chỉ hữu hạn số hạng trong $\sum_nP(|X_n|>q)$ khác không, nên tổng hữu hạn.`),b(String.raw`Directly $1/n\to0$ for every outcome, so convergence is almost sure.`,String.raw`Trực tiếp $1/n\to0$ tại mọi kết quả, nên hội tụ hầu chắc.`)]},
      {prompt:b(String.raw`On uniform U in [0,1], let $X_n=1_{[0,2^{-n}]}(U)$ and X=0. Prove a.s. convergence using summable error probabilities.`,String.raw`Với U đều trên [0,1], đặt $X_n=1_{[0,2^{-n}]}(U)$ và X=0. Dùng tổng xác suất sai số hữu hạn chứng minh hội tụ hầu chắc.`),solution:[b(String.raw`For any rational $0<q<1$, $P(|X_n|>q)=2^{-n}$; for q>=1 it is zero.`,String.raw`Với hữu tỷ $0<q<1$, $P(|X_n|>q)=2^{-n}$; với q>=1 bằng không.`),b(String.raw`The error probabilities sum to at most $\sum_n2^{-n}<\infty$ at every rational threshold.`,String.raw`Tổng xác suất sai số không vượt $\sum_n2^{-n}<\infty$ tại mọi ngưỡng hữu tỷ.`),b(String.raw`Borel–Cantelli at countably many thresholds yields $X_n\to0$ a.s.; pointwise, only U=0 could remain in all intervals and that point is null.`,String.raw`Borel–Cantelli tại các ngưỡng đếm được cho $X_n\to0$ hầu chắc; từng điểm, chỉ U=0 có thể còn trong mọi khoảng nhưng điểm này có xác suất không.`)]},
      {prompt:b(String.raw`Let independent events have $P(A_n)=2^{-n}$ and set $X_n=2^n1_{A_n}$. Show $X_n\to0$ a.s. although $E[X_n]=1$.`,String.raw`Cho các biến cố độc lập có $P(A_n)=2^{-n}$ và đặt $X_n=2^n1_{A_n}$. Chứng minh $X_n\to0$ hầu chắc dù $E[X_n]=1$.`),solution:[b(String.raw`For each fixed rational q>0, when $2^n>q$ the error event is exactly A_n; its probability tail is summable.`,String.raw`Với q>0 hữu tỷ cố định, khi $2^n>q$ biến cố sai số chính là A_n; đuôi xác suất có tổng hữu hạn.`),b(String.raw`Borel–Cantelli I gives only finitely many A_n a.s.; outside that null exception, $X_n=0$ eventually.`,String.raw`Borel–Cantelli I cho chỉ hữu hạn A_n xảy ra hầu chắc; ngoài tập không đó, cuối cùng $X_n=0$.`),b(String.raw`Yet $E[X_n]=2^nP(A_n)=1$ for every n, so a.s. convergence need not imply convergence of means without UI.`,String.raw`Dù vậy $E[X_n]=2^nP(A_n)=1$ với mọi n, nên hội tụ hầu chắc không kéo theo hội tụ trung bình nếu thiếu UI.`)]}
    ],
    reviewNote:'Countability of positive rational thresholds is what preserves a probability-one intersection. The third example checks a.s. convergence while its expectations stay one, exposing the need for additional integrability to pass limits through expectations.',
    sourceIds:['p-mit18175']
  },
  'm2-w035-e1': {
    application:b('On a finite partition, conditional expectation assigns each block its probability-weighted average, making the result constant on that block.','Trên phân hoạch hữu hạn, kỳ vọng có điều kiện gán cho mỗi khối trung bình có trọng số xác suất, nên kết quả hằng trên khối.'),
    formula:b(String.raw`$Z=E[X\mid\mathcal G],\quad Z|_B=\frac{E[X1_B]}{P(B)}\quad\text{for every partition block }B\text{ with }P(B)>0.$`,String.raw`$Z=E[X\mid\mathcal G],\quad Z|_B=\frac{E[X1_B]}{P(B)}\quad\text{với mỗi khối phân hoạch }B\text{ có }P(B)>0.$`),
    steps:[b(String.raw`On the equiprobable states {1,2}, the average of X values 0 and 2 is 1; on {3,4}, average 4 and 6 to get 5.`,String.raw`Trên các trạng thái đồng xác suất {1,2}, trung bình giá trị X là 0 và 2 bằng 1; trên {3,4}, trung bình 4 và 6 bằng 5.`),b(String.raw`Thus Z=(1,1,5,5). On each block, $E[Z1_B]=E[X1_B]$: both equal 1/2 on the first block and 5/2 on the second.`,String.raw`Vậy Z=(1,1,5,5). Trên mỗi khối, $E[Z1_B]=E[X1_B]$: cả hai bằng 1/2 ở khối đầu và 5/2 ở khối sau.`),b(String.raw`Adding block integrals gives $E[Z]=E[X]=3$; every G-event is a union of these blocks.`,String.raw`Cộng tích phân các khối cho $E[Z]=E[X]=3$; mọi biến cố G là hợp của các khối này.`)],
    primarySolution:[b(String.raw`Average within block {1,2}: $(0+2)/2=1$.`,String.raw`Lấy trung bình khối {1,2}: $(0+2)/2=1$.`),b(String.raw`Average within block {3,4}: $(4+6)/2=5$. Hence $E[X\mid G]=(1,1,5,5)$.`,String.raw`Lấy trung bình khối {3,4}: $(4+6)/2=5$. Vì vậy $E[X\mid G]=(1,1,5,5)$.`),b(String.raw`On the first block, $\int X\,dP=\int Z\,dP=(0+2)/4=1/2$; on the second both equal $(4+6)/4=5/2$.`,String.raw`Trên khối đầu, $\int X\,dP=\int Z\,dP=(0+2)/4=1/2$; trên khối hai cùng bằng $(4+6)/4=5/2$.`),b(String.raw`On Ω both integrals equal 3; additivity verifies every union of blocks.`,String.raw`Trên Ω hai tích phân đều bằng 3; tính cộng xác minh mọi hợp khối.`)],
    companions:[
      {prompt:b(String.raw`Four outcomes have probabilities $(1/8,3/8,1/4,1/4)$, $X=(0,4,2,6)$, and blocks B={1,2}, Bᶜ={3,4}. Find the conditional mean on each block and E[X|G].`,String.raw`Bốn kết quả có xác suất $(1/8,3/8,1/4,1/4)$, $X=(0,4,2,6)$, khối B={1,2}, Bᶜ={3,4}. Tìm trung bình có điều kiện trên mỗi khối và E[X|G].`),solution:[b(String.raw`The mass of B is 1/2 and its weighted X-sum is $(1/8)0+(3/8)4=3/2$, so its mean is 3.`,String.raw`Khối lượng B là 1/2, tổng X có trọng số là $(1/8)0+(3/8)4=3/2$, nên trung bình bằng 3.`),b(String.raw`The complement has mass 1/2 and weighted sum $(1/4)2+(1/4)6=2$, so its mean is 4.`,String.raw`Phần bù có khối lượng 1/2 và tổng có trọng số $(1/4)2+(1/4)6=2$, nên trung bình bằng 4.`),b(String.raw`Thus Z=(3,3,4,4) and $E[Z]=3(1/2)+4(1/2)=7/2=E[X]$.`,String.raw`Vậy Z=(3,3,4,4) và $E[Z]=3(1/2)+4(1/2)=7/2=E[X]$.`)]},
      {prompt:b(String.raw`Six equally likely sensor states are split into B={1,2,3} and Bᶜ={4,5,6}; readings are $X=(2,4,8,1,3,5)$. Compute E[X|G].`,String.raw`Sáu trạng thái cảm biến đồng xác suất chia B={1,2,3} và Bᶜ={4,5,6}; số đo là $X=(2,4,8,1,3,5)$. Tính E[X|G].`),solution:[b(String.raw`The first block mean is $(2+4+8)/3=14/3$.`,String.raw`Trung bình khối đầu là $(2+4+8)/3=14/3$.`),b(String.raw`The second block mean is $(1+3+5)/3=3$.`,String.raw`Trung bình khối hai là $(1+3+5)/3=3$.`),b(String.raw`The conditional expectation is $(14/3,14/3,14/3,3,3,3)$; its mean is $(14/3+3)/2=23/6=E[X]$.`,String.raw`Kỳ vọng có điều kiện là $(14/3,14/3,14/3,3,3,3)$; trung bình là $(14/3+3)/2=23/6=E[X]$.`)]},
      {prompt:b(String.raw`Three outcomes have probabilities $(1/5,3/10,1/2)$, values $X=(2,8,10)$, and partition blocks {a,b} and {c}. Find the block-constant conditional expectation.`,String.raw`Ba kết quả có xác suất $(1/5,3/10,1/2)$, giá trị $X=(2,8,10)$, phân hoạch thành {a,b} và {c}. Tìm kỳ vọng có điều kiện hằng theo khối.`),solution:[b(String.raw`The first block has mass 1/2 and weighted sum $(1/5)2+(3/10)8=14/5$, giving mean $(14/5)/(1/2)=28/5$.`,String.raw`Khối đầu có khối lượng 1/2 và tổng có trọng số $(1/5)2+(3/10)8=14/5$, cho trung bình $(14/5)/(1/2)=28/5$.`),b(String.raw`The singleton block {c} has conditional mean 10.`,String.raw`Khối đơn {c} có trung bình có điều kiện bằng 10.`),b(String.raw`Therefore $E[X|G]=(28/5,28/5,10)$; its expectation is $(1/2)(28/5)+(1/2)10=39/5=E[X]$.`,String.raw`Vì vậy $E[X|G]=(28/5,28/5,10)$; kỳ vọng là $(1/2)(28/5)+(1/2)10=39/5=E[X]$.`)]}
    ],
    reviewNote:'Each block in the primary partition has positive probability 1/2, so its conditional mean is uniquely determined by the block integral. Additivity extends the check from generating blocks to every G-event.',
    sourceIds:['p-mit6436']
  },
  'm2-w035-e2': {
    application:b('Uniqueness follows by testing the signed difference on measurable level sets where it is bounded away from zero.','Tính duy nhất suy ra khi thử hiệu có dấu trên các tập mức đo được mà hiệu bị chặn cách không.'),
    formula:b(String.raw`$Z,W\in L^1,\quad \int_A Z\,dP=\int_AW\,dP\ \forall A\in\mathcal G\quad\Longrightarrow\quad Z=W\text{ a.s.}$`,String.raw`$Z,W\in L^1,\quad \int_A Z\,dP=\int_AW\,dP\ \forall A\in\mathcal G\quad\Longrightarrow\quad Z=W\text{ h.c.}$`),
    steps:[b(String.raw`Set $D=Z-W$. The defining identities imply $\int_A D\,dP=0$ for every $A\in G$.`,String.raw`Đặt $D=Z-W$. Đồng nhất thức định nghĩa suy ra $\int_A D\,dP=0$ với mọi $A\in G$.`),b(String.raw`For each k>=1, $A_k=\{D\ge1/k\}\in G$; on it $D\ge1/k$, so $0=\int_{A_k}D\,dP\ge P(A_k)/k$ and $P(A_k)=0$.`,String.raw`Với mỗi k>=1, $A_k=\{D\ge1/k\}\in G$; trên đó $D\ge1/k$, nên $0=\int_{A_k}D\,dP\ge P(A_k)/k$ và $P(A_k)=0$.`),b(String.raw`Since $\{D>0\}=\cup_kA_k$, that positive-difference event is null.`,String.raw`Vì $\{D>0\}=\cup_kA_k$, biến cố hiệu dương là tập không.`),b(String.raw`Repeat with W−Z to make $\{D<0\}$ null; therefore Z=W almost surely.`,String.raw`Lặp với W−Z để $\{D<0\}$ cũng là tập không; do đó Z=W hầu chắc.`)],
    primarySolution:[b(String.raw`Let $D=Z-W$. On each level event $D_k=\{D\ge1/k\}\in G$, the integral identity gives $\int_{D_k}D\,dP=0$.`,String.raw`Đặt $D=Z-W$. Trên mỗi biến cố mức $D_k=\{D\ge1/k\}\in G$, đồng nhất thức tích phân cho $\int_{D_k}D\,dP=0$.`),b(String.raw`But $D\ge1/k$ on D_k, so $0\ge P(D_k)/k$ and P(D_k)=0.`,String.raw`Nhưng $D\ge1/k$ trên D_k, nên $0\ge P(D_k)/k$ và P(D_k)=0.`),b(String.raw`The countable union of the D_k is {Z>W}, hence P(Z>W)=0.`,String.raw`Hợp đếm được các D_k là {Z>W}, nên P(Z>W)=0.`),b(String.raw`Applying the same argument to W−Z gives P(W>Z)=0; thus P(Z≠W)=0.`,String.raw`Áp dụng tương tự cho W−Z được P(W>Z)=0; do đó P(Z≠W)=0.`)],
    companions:[
      {prompt:b(String.raw`On three atoms with probabilities $(1/2,1/2,0)$, let G be all subsets, X=(2,4,0), Z=(2,4,0), W=(2,4,9). Check whether Z and W satisfy the same conditional-expectation identities.`,String.raw`Trên ba nguyên tử có xác suất $(1/2,1/2,0)$, lấy G gồm mọi tập, X=(2,4,0), Z=(2,4,0), W=(2,4,9). Kiểm tra Z,W có cùng thỏa các đồng nhất thức kỳ vọng có điều kiện không.`),solution:[b(String.raw`At the two positive-mass atoms, both candidates equal X.`,String.raw`Tại hai nguyên tử khối lượng dương, cả hai ứng viên đều bằng X.`),b(String.raw`At the third atom the values differ, but its probability is zero, so every event integral is unchanged.`,String.raw`Tại nguyên tử thứ ba hai giá trị khác nhau nhưng xác suất bằng không, nên mọi tích phân trên biến cố không đổi.`),b(String.raw`Both are measurable and integrable and satisfy all G-integral identities; they agree almost surely.`,String.raw`Cả hai đo được, khả tích và thỏa mọi đồng nhất thức tích phân G; chúng bằng nhau hầu chắc.`)]},
      {prompt:b(String.raw`On a fair four-state space, G has blocks {1,2},{3,4}, and X=(0,2,4,6). A proposed block-constant candidate is W=(3/2,3/2,5,5). Which defining identity fails?`,String.raw`Trên không gian bốn trạng thái đều, G có khối {1,2},{3,4}, X=(0,2,4,6). Ứng viên hằng khối W=(3/2,3/2,5,5). Đồng nhất thức định nghĩa nào thất bại?`),solution:[b(String.raw`On {3,4}, X and W both integrate to $(4+6)/4=5/2$.`,String.raw`Trên {3,4}, X và W đều có tích phân $(4+6)/4=5/2$.`),b(String.raw`On {1,2}, $\int X\,dP=(0+2)/4=1/2$, while $\int W\,dP=(3/2+3/2)/4=3/4$.`,String.raw`Trên {1,2}, $\int X\,dP=(0+2)/4=1/2$, còn $\int W\,dP=(3/2+3/2)/4=3/4$.`),b(String.raw`The block identity fails, so W cannot be a conditional expectation; the unique valid first-block value is 1.`,String.raw`Đồng nhất thức khối thất bại nên W không thể là kỳ vọng có điều kiện; giá trị hợp lệ duy nhất ở khối đầu là 1.`)]},
      {prompt:b(String.raw`On [0,1] with Lebesgue probability and trivial G={empty,Ω}, X=1_[0,1/2]. Show that any conditional expectation candidate must equal 1/2 a.s.`,String.raw`Trên [0,1] với xác suất Lebesgue và G tầm thường {rỗng,Ω}, X=1_[0,1/2]. Chứng minh mọi ứng viên kỳ vọng có điều kiện phải bằng 1/2 hầu chắc.`),solution:[b(String.raw`A G-measurable real random variable is constant almost surely because its sublevel events can only be empty or Ω.`,String.raw`Biến ngẫu nhiên thực G-đo được phải hằng hầu chắc vì các biến cố mức chỉ có thể rỗng hoặc Ω.`),b(String.raw`Write the candidate as c a.s.; the identity on Ω forces $c=E[X]=1/2$.`,String.raw`Viết ứng viên là c hầu chắc; đồng nhất thức trên Ω buộc $c=E[X]=1/2$.`),b(String.raw`Thus the candidate is unique up to null sets, as the general level-set proof states.`,String.raw`Vậy ứng viên duy nhất tới tập không, đúng như chứng minh tổng quát bằng tập mức.`)]}
    ],
    reviewNote:'The proof uses integrability to define each difference integral and G-measurability of level sets. Testing both signs makes the exceptional set {Z≠W} a countable union of null sets.',
    sourceIds:['p-mit6436']
  },
  'm2-w035-e3': {
    application:b('With a two-block sigma-algebra, measurability forces a conditional expectation to have one constant on A and another on its complement.','Với sigma-đại số hai khối, tính đo được buộc kỳ vọng có điều kiện nhận một hằng số trên A và một hằng số khác trên phần bù.'),
    formula:b(String.raw`$0<P(A)<1,\ X\in L^1:\quad E[X\mid\sigma(A)]=\frac{E[X1_A]}{P(A)}1_A+\frac{E[X1_{A^c}]}{P(A^c)}1_{A^c}.$`,String.raw`$0<P(A)<1,\ X\in L^1:\quad E[X\mid\sigma(A)]=\frac{E[X1_A]}{P(A)}1_A+\frac{E[X1_{A^c}]}{P(A^c)}1_{A^c}.$`),
    steps:[b(String.raw`Any $\sigma(A)$-measurable block-constant candidate has form $Z=u1_A+v1_{A^c}$.`,String.raw`Mọi ứng viên hằng khối đo được theo $\sigma(A)$ có dạng $Z=u1_A+v1_{A^c}$.`),b(String.raw`Testing on A gives $uP(A)=E[X1_A]$, hence $u=E[X1_A]/P(A)$; testing Aᶜ similarly determines v.`,String.raw`Thử trên A cho $uP(A)=E[X1_A]$, nên $u=E[X1_A]/P(A)$; thử trên Aᶜ xác định v tương tự.`),b(String.raw`These values give the required identity on ∅, A, Aᶜ, and Ω; these are all events in $\sigma(A)$.`,String.raw`Các giá trị này thỏa đồng nhất thức trên ∅, A, Aᶜ, Ω; đó là mọi biến cố trong $\sigma(A)$.`)],
    primarySolution:[b(String.raw`Write $Z=u1_A+v1_{A^c}$ because Z is measurable with respect to the two-block sigma-algebra.`,String.raw`Viết $Z=u1_A+v1_{A^c}$ vì Z đo được theo sigma-đại số hai khối.`),b(String.raw`The identity on A forces $uP(A)=E[X1_A]$, so $u=E[X1_A]/P(A)$.`,String.raw`Đồng nhất thức trên A buộc $uP(A)=E[X1_A]$, nên $u=E[X1_A]/P(A)$.`),b(String.raw`On Aᶜ it forces $v=E[X1_{A^c}]/P(A^c)$.`,String.raw`Trên Aᶜ, đồng nhất thức buộc $v=E[X1_{A^c}]/P(A^c)$.`),b(String.raw`The candidate built from these constants is measurable and its integrals match on each block; additivity proves the identity for every G-event.`,String.raw`Ứng viên tạo từ hai hằng số này đo được và có tích phân đúng trên mỗi khối; tính cộng chứng minh đồng nhất thức trên mọi biến cố G.`)],
    companions:[
      {prompt:b(String.raw`Let U be uniform on [0,1], A=[0,1/3], and X(U)=U. Find E[X|σ(A)] on A and Aᶜ, then check its overall mean.`,String.raw`Cho U đều trên [0,1], A=[0,1/3], X(U)=U. Tìm E[X|σ(A)] trên A,Aᶜ rồi kiểm tra trung bình chung.`),solution:[b(String.raw`On A, $E[X1_A]=\int_0^{1/3}u\,du=1/18$ and $P(A)=1/3$, so the conditional mean is 1/6.`,String.raw`Trên A, $E[X1_A]=\int_0^{1/3}u\,du=1/18$ và $P(A)=1/3$, nên trung bình có điều kiện bằng 1/6.`),b(String.raw`On Aᶜ, $E[X1_{A^c}]=1/2-1/18=4/9$ and $P(A^c)=2/3$, giving mean 2/3.`,String.raw`Trên Aᶜ, $E[X1_{A^c}]=1/2-1/18=4/9$ và $P(A^c)=2/3$, cho trung bình 2/3.`),b(String.raw`The block-constant variable has mean $(1/3)(1/6)+(2/3)(2/3)=1/2=E[U]$.`,String.raw`Biến hằng khối có trung bình $(1/3)(1/6)+(2/3)(2/3)=1/2=E[U]$.`)]},
      {prompt:b(String.raw`Four equiprobable readings are $X=(0,6,2,10)$ and A={1,2}. Find the conditional value on each of A and Aᶜ.`,String.raw`Bốn số đo đồng xác suất là $X=(0,6,2,10)$ và A={1,2}. Tìm giá trị có điều kiện trên A và Aᶜ.`),solution:[b(String.raw`The block A mean is $(0+6)/2=3$.`,String.raw`Trung bình khối A là $(0+6)/2=3$.`),b(String.raw`The complementary block mean is $(2+10)/2=6$.`,String.raw`Trung bình khối đối diện là $(2+10)/2=6$.`),b(String.raw`Therefore $E[X|\sigma(A)]=(3,3,6,6)$, and its overall mean is $(3+6)/2=9/2=E[X]$.`,String.raw`Vậy $E[X|\sigma(A)]=(3,3,6,6)$, trung bình chung là $(3+6)/2=9/2=E[X]$.`)]},
      {prompt:b(String.raw`A has probability 1/4. An integrable payoff X equals 8 on A and 0 on Aᶜ. Compute E[X|σ(A)] and verify both block integrals.`,String.raw`A có xác suất 1/4. Khoản trả khả tích X bằng 8 trên A và 0 trên Aᶜ. Tính E[X|σ(A)] và kiểm tra tích phân hai khối.`),solution:[b(String.raw`On A, X is already constant 8, so the conditional value is 8.`,String.raw`Trên A, X đã hằng bằng 8, nên giá trị có điều kiện là 8.`),b(String.raw`On Aᶜ, X is zero, so the conditional value is 0.`,String.raw`Trên Aᶜ, X bằng không, nên giá trị có điều kiện là 0.`),b(String.raw`The A integrals are $8(1/4)=2$ on both sides; the Aᶜ integrals are zero.`,String.raw`Tích phân trên A bằng $8(1/4)=2$ ở cả hai vế; trên Aᶜ đều bằng không.`)]}
    ],
    reviewNote:'Both blocks have positive probability by hypothesis, so division is legal. The constructed block-constant variable is integrable because its block integrals are finite for X in L1.',
    sourceIds:['p-mit6436']
  },
  'm2-w035-e4': {
    application:b('Conditional expectations are unique only up to null sets; a modification on a null set remains a version only if it stays measurable for the conditioning sigma-algebra.','Kỳ vọng có điều kiện chỉ duy nhất tới tập không; sửa trên tập không vẫn là một phiên bản nếu còn đo được theo sigma-đại số điều kiện.'),
    formula:b(String.raw`$Z\text{ is a version of }E[X\mid\mathcal G]\iff Z\in L^1,\ Z\ \mathcal G\text{-measurable, and }\int_AZ\,dP=\int_AX\,dP\ \forall A\in\mathcal G.$`,String.raw`$Z\text{ là phiên bản của }E[X\mid\mathcal G]\iff Z\in L^1,\ Z\ \mathcal G\text{-đo được, và }\int_AZ\,dP=\int_AX\,dP\ \forall A\in\mathcal G.$`),
    steps:[b(String.raw`The four sets $\emptyset,\{0\},(0,1],[0,1]$ form a sigma-field, and the level sets of $W=1_{\{0\}}$ belong to it, so W is G-measurable.`,String.raw`Bốn tập $\emptyset,\{0\},(0,1],[0,1]$ tạo sigma-đại số; các tập mức của $W=1_{\{0\}}$ thuộc đó nên W đo được theo G.`),b(String.raw`The singleton {0} has Lebesgue probability zero; thus $E|W|=0$ and every G-event integral of W is zero, matching X=0 and Z=0.`,String.raw`Tập đơn {0} có xác suất Lebesgue bằng không; do đó $E|W|=0$ và mọi tích phân G của W bằng không, khớp X=0 và Z=0.`),b(String.raw`At 0, W differs from Z, yet they agree a.s. For the trivial sigma-field, {W>1/2}={0} is absent, so W is not measurable there.`,String.raw`Tại 0, W khác Z nhưng hai biến bằng nhau hầu chắc. Với sigma-đại số tầm thường, {W>1/2}={0} không thuộc đó nên W không đo được.`)],
    primarySolution:[b(String.raw`The specified four sets are closed under complements and countable unions. Since $\{W=1\}=\{0\}$ and $\{W=0\}=(0,1]$ belong to G, W is G-measurable.`,String.raw`Bốn tập đã nêu đóng dưới phép bù và hợp đếm được. Vì $\{W=1\}=\{0\}$ và $\{W=0\}=(0,1]$ thuộc G, W đo được theo G.`),b(String.raw`The point {0} is null, so $E|W|=0$ and $\int_AW\,dP=0=\int_AX\,dP$ for every A in G. Z=0 also satisfies the identities.`,String.raw`Điểm {0} có độ đo không, nên $E|W|=0$ và $\int_AW\,dP=0=\int_AX\,dP$ với mọi A thuộc G. Z=0 cũng thỏa các đồng nhất thức.`),b(String.raw`Although $W(0)=1\ne Z(0)$, the versions agree outside a null set.`,String.raw`Dù $W(0)=1\ne Z(0)$, hai phiên bản bằng nhau ngoài tập không.`),b(String.raw`Under the trivial sigma-field, the level event $\{W>1/2\}=\{0\}$ is not measurable, so W is not a valid version there.`,String.raw`Theo sigma-đại số tầm thường, tập mức $\{W>1/2\}=\{0\}$ không đo được, nên W không phải phiên bản hợp lệ.`)],
    companions:[
      {prompt:b(String.raw`A finite space has masses $(1/2,1/2,0)$, full sigma-field, and X=(2,4,0). Compare Z=(2,4,0) with W=(2,4,9) as versions of E[X|G].`,String.raw`Không gian hữu hạn có khối lượng $(1/2,1/2,0)$, sigma-đại số đầy đủ và X=(2,4,0). So sánh Z=(2,4,0) với W=(2,4,9) như các phiên bản E[X|G].`),solution:[b(String.raw`Both candidates are measurable and integrable on the finite space.`,String.raw`Cả hai ứng viên đo được và khả tích trên không gian hữu hạn.`),b(String.raw`They equal X on the first two atoms, while the third atom has probability zero; hence their integral over every event equals that of X.`,String.raw`Chúng bằng X trên hai nguyên tử đầu, còn nguyên tử thứ ba có xác suất không; vì vậy tích phân trên mọi biến cố bằng tích phân của X.`),b(String.raw`They differ at that null atom but agree almost surely, so both are versions.`,String.raw`Chúng khác tại nguyên tử không nhưng bằng nhau hầu chắc, nên cả hai đều là phiên bản.`)]},
      {prompt:b(String.raw`On [0,1] with Lebesgue probability let G=σ({1/2}) and X=0. Set W=3 1_{ {1/2} }. Check whether W is a version of E[X|G].`,String.raw`Trên [0,1] với xác suất Lebesgue, cho G=σ({1/2}) và X=0. Đặt W=3 1_{ {1/2} }. Kiểm tra W có là phiên bản E[X|G] không.`),solution:[b(String.raw`The singleton and its complement generate G, so W is G-measurable.`,String.raw`Tập đơn và phần bù sinh G, nên W đo được theo G.`),b(String.raw`Since the singleton has measure zero, W is integrable with $E|W|=0$ and every G-event integral is zero.`,String.raw`Vì tập đơn có độ đo không, W khả tích với $E|W|=0$ và tích phân trên mọi biến cố G bằng không.`),b(String.raw`Thus W satisfies all defining identities for X=0, despite W(1/2)=3.`,String.raw`Vì vậy W thỏa mọi đồng nhất thức định nghĩa cho X=0, dù W(1/2)=3.`)]},
      {prompt:b(String.raw`On outcomes {a,b,c} with probabilities $(1/3,2/3,0)$ and G=all subsets, let X=(5,-1,0). Define Z=(5,-1,0) and V=(5,-1,100). Verify both are versions.`,String.raw`Trên các kết quả {a,b,c} có xác suất $(1/3,2/3,0)$ và G gồm mọi tập, cho X=(5,-1,0), Z=(5,-1,0), V=(5,-1,100). Kiểm tra cả hai là phiên bản.`),solution:[b(String.raw`Z=X everywhere, so it plainly satisfies measurability and all event integrals.`,String.raw`Z=X tại mọi điểm nên hiển nhiên đo được và thỏa mọi tích phân biến cố.`),b(String.raw`V differs only at c, whose probability is zero; for any subset A, its weighted integral is unchanged.`,String.raw`V chỉ khác tại c có xác suất bằng không; với mọi tập con A, tích phân có trọng số không đổi.`),b(String.raw`Both are integrable versions and Z=V almost surely.`,String.raw`Cả hai là phiên bản khả tích và Z=V hầu chắc.`)]}
    ],
    reviewNote:'The null modification preserves every event integral because the changed point has probability zero. Measurability remains a separate requirement; the trivial-sigma-field check shows that integral agreement alone is insufficient.',
    sourceIds:['p-mit6436']
  },
  'm2-w035-e5': {
    application:b('The event integral definition extends from indicators to bounded measurable test functions by simple approximation.','Định nghĩa tích phân trên biến cố mở rộng từ hàm chỉ thị sang hàm thử đo được bị chặn bằng xấp xỉ hàm đơn.'),
    formula:b(String.raw`$Z=E[X\mid\mathcal G],\ H\text{ bounded and }\mathcal G\text{-measurable}\quad\Longrightarrow\quad E[HZ]=E[HX],\quad X\in L^1.$`,String.raw`$Z=E[X\mid\mathcal G],\ H\text{ bị chặn và }\mathcal G\text{-đo được}\quad\Longrightarrow\quad E[HZ]=E[HX],\quad X\in L^1.$`),
    steps:[b(String.raw`For simple $H=\sum_jc_j1_{A_j}$ with A_j in G, multiply the defining identity for each A_j by c_j and add.`,String.raw`Với H đơn $H=\sum_jc_j1_{A_j}$, A_j thuộc G, nhân đồng nhất thức định nghĩa trên từng A_j với c_j rồi cộng.`),b(String.raw`Approximate bounded G-measurable H uniformly by bounded simple G-measurable H_m.`,String.raw`Xấp xỉ đều H G-đo được bị chặn bằng hàm đơn G-đo được bị chặn H_m.`),b(String.raw`The errors satisfy $|E[(H_m-H)X]|\le\|H_m-H\|_\infty E|X|$, and similarly for Z; both vanish, so pass to the limit.`,String.raw`Sai số thỏa $|E[(H_m-H)X]|\le\|H_m-H\|_\infty E|X|$, tương tự với Z; cả hai tiến về không nên lấy được giới hạn.`),b(String.raw`An unbounded H needs extra conditions ensuring HX and HZ are integrable and the truncation limit is valid.`,String.raw`H không bị chặn cần điều kiện bổ sung để HX,HZ khả tích và giới hạn cắt cụt hợp lệ.`)],
    primarySolution:[b(String.raw`First let $H=\sum_jc_j1_{A_j}$ be simple with A_j in G.`,String.raw`Trước hết cho $H=\sum_jc_j1_{A_j}$ là hàm đơn với A_j thuộc G.`),b(String.raw`Linearity and the event identities give $E[HZ]=\sum_jc_jE[1_{A_j}Z]=\sum_jc_jE[1_{A_j}X]=E[HX]$.`,String.raw`Tính tuyến tính và đồng nhất thức biến cố cho $E[HZ]=\sum_jc_jE[1_{A_j}Z]=\sum_jc_jE[1_{A_j}X]=E[HX]$.`),b(String.raw`For bounded measurable H, choose uniformly bounded G-simple H_m converging pointwise (indeed uniformly) to H.`,String.raw`Với H đo được bị chặn, chọn H_m đơn G-đo được bị chặn đều và hội tụ điểm (thậm chí đều) tới H.`),b(String.raw`Since X,Z are integrable, uniform approximation makes both product expectations converge, proving the identity. Unbounded H lacks this bound and needs extra integrability.`,String.raw`Vì X,Z khả tích, xấp xỉ đều khiến hai kỳ vọng tích hội tụ, chứng minh đồng nhất thức. H không bị chặn thiếu chặn này và cần thêm khả tích.`)],
    companions:[
      {prompt:b(String.raw`On four equally likely states, G-blocks are {1,2},{3,4}, X=(0,2,4,6), and Z=E[X|G]=(1,1,5,5). Let H=(2,2,-1,-1). Compute E[HZ] and E[HX].`,String.raw`Trên bốn trạng thái đồng xác suất, khối G là {1,2},{3,4}, X=(0,2,4,6), Z=E[X|G]=(1,1,5,5). Cho H=(2,2,-1,-1). Tính E[HZ] và E[HX].`),solution:[b(String.raw`H is G-measurable and bounded, taking value 2 on the first block and −1 on the second.`,String.raw`H G-đo được và bị chặn, nhận giá trị 2 ở khối đầu và −1 ở khối sau.`),b(String.raw`$E[HZ]=(2+2-5-5)/4=-3/2$.`,String.raw`$E[HZ]=(2+2-5-5)/4=-3/2$.`),b(String.raw`$E[HX]=(0+4-4-6)/4=-3/2$, confirming equality.`,String.raw`$E[HX]=(0+4-4-6)/4=-3/2$, xác nhận hai vế bằng nhau.`)]},
      {prompt:b(String.raw`On [0,1] with U uniform, take G=σ(U), X=U^2, Z=X, H=1_[0,1/3](U). Verify the test-function identity by integration.`,String.raw`Trên [0,1] với U đều, lấy G=σ(U), X=U^2, Z=X, H=1_[0,1/3](U). Kiểm tra đồng nhất thức hàm thử bằng tích phân.`),solution:[b(String.raw`H is bounded and G-measurable because it is an indicator of a set determined by U.`,String.raw`H bị chặn và G-đo được vì là hàm chỉ thị của tập xác định bởi U.`),b(String.raw`Both products equal $U^2 1_{[0,1/3]}(U)$.`,String.raw`Hai tích đều bằng $U^2 1_{[0,1/3]}(U)$.`),b(String.raw`Their expectation is $\int_0^{1/3}u^2du=1/81$, so $E[HZ]=E[HX]$.`,String.raw`Kỳ vọng của chúng là $\int_0^{1/3}u^2du=1/81$, nên $E[HZ]=E[HX]$.`)]},
      {prompt:b(String.raw`On six equally likely states, G has blocks B={1,2,3}, Bᶜ={4,5,6}, X=(0,3,6,2,4,6). Let Z be the block means and H=(1,1,1,2,2,2). Compare E[HZ] and E[HX].`,String.raw`Trên sáu trạng thái đồng xác suất, G có khối B={1,2,3}, Bᶜ={4,5,6}, X=(0,3,6,2,4,6). Cho Z là trung bình khối và H=(1,1,1,2,2,2). So sánh E[HZ], E[HX].`),solution:[b(String.raw`The block means are $Z=3$ on B and $Z=4$ on Bᶜ.`,String.raw`Trung bình khối là $Z=3$ trên B và $Z=4$ trên Bᶜ.`),b(String.raw`$E[HZ]=(3+3+3+8+8+8)/6=33/6=11/2$.`,String.raw`$E[HZ]=(3+3+3+8+8+8)/6=33/6=11/2$.`),b(String.raw`$E[HX]=(0+3+6+4+8+12)/6=33/6=11/2$, so the identity holds.`,String.raw`$E[HX]=(0+3+6+4+8+12)/6=33/6=11/2$, nên đồng nhất thức đúng.`)]}
    ],
    reviewNote:'Uniform simple approximation is valid for bounded measurable H. Integrability of X and its conditional expectation controls the approximation error; for unbounded H, the product expectations may not exist.',
    sourceIds:['p-mit6436']
  },
  'm2-w036-e1': {
    application:b('Average within a finer partition, then average across its blocks to recover conditioning on a coarser sigma-algebra.','Lấy trung bình trong phân hoạch mịn hơn rồi lấy trung bình các khối để thu lại kỳ vọng theo sigma-đại số thô hơn.'),
    formula:b(String.raw`$\mathcal H\subseteq\mathcal G,\ X\in L^1:\quad E[E[X\mid\mathcal G]\mid\mathcal H]=E[X\mid\mathcal H]\text{ a.s.}$`,String.raw`$\mathcal H\subseteq\mathcal G,\ X\in L^1:\quad E[E[X\mid\mathcal G]\mid\mathcal H]=E[X\mid\mathcal H]\text{ h.c.}$`),
    steps:[b(String.raw`For the given four states, the G-block means on {1,2} and {3,4} are $(0+2)/2=1$ and $(4+6)/2=5$.`,String.raw`Với bốn trạng thái đã cho, trung bình khối G trên {1,2},{3,4} lần lượt là $(0+2)/2=1$ và $(4+6)/2=5$.`),b(String.raw`Thus $E[X|G]=(1,1,5,5)$. Conditioning on trivial H takes its overall average, $(1+1+5+5)/4=3$.`,String.raw`Vậy $E[X|G]=(1,1,5,5)$. Điều kiện theo H tầm thường lấy trung bình chung $(1+1+5+5)/4=3$.`),b(String.raw`Directly $E[X]=(0+2+4+6)/4=3$, so the iterated and direct conditional expectations agree.`,String.raw`Tính trực tiếp $E[X]=(0+2+4+6)/4=3$, nên kỳ vọng lặp và trực tiếp bằng nhau.`)],
    primarySolution:[b(String.raw`Average X within the two G-blocks to get $E[X|G]=(1,1,5,5)$.`,String.raw`Lấy trung bình X trong hai khối G được $E[X|G]=(1,1,5,5)$.`),b(String.raw`The trivial sigma-field conditional expectation is constant and equals the mean, so $E[E[X|G]|H]=(1+1+5+5)/4=3$.`,String.raw`Kỳ vọng theo sigma-đại số tầm thường là hằng bằng trung bình, nên $E[E[X|G]|H]=(1+1+5+5)/4=3$.`),b(String.raw`Also $E[X|H]=E[X]=(0+2+4+6)/4=3$.`,String.raw`Đồng thời $E[X|H]=E[X]=(0+2+4+6)/4=3$.`),b(String.raw`Both routes give 3, verifying the tower identity in this finite example.`,String.raw`Cả hai cách đều cho 3, xác minh tính chất tháp trong ví dụ hữu hạn này.`)],
    companions:[
      {prompt:b(String.raw`Six equally likely states have X=(1,3,5,2,4,6); G-blocks are {1,2},{3,4},{5,6}, and H is trivial. Compute both sides of the tower property.`,String.raw`Sáu trạng thái đồng xác suất có X=(1,3,5,2,4,6); khối G là {1,2},{3,4},{5,6}, còn H tầm thường. Tính hai vế tính chất tháp.`),solution:[b(String.raw`The three G-block means are 2, 7/2, and 5.`,String.raw`Ba trung bình khối G là 2, 7/2 và 5.`),b(String.raw`Their equally weighted mean is $(2+7/2+5)/3=7/2$.`,String.raw`Trung bình đồng trọng số của chúng là $(2+7/2+5)/3=7/2$.`),b(String.raw`The original mean is $(1+3+5+2+4+6)/6=7/2$, so the tower values agree.`,String.raw`Trung bình ban đầu là $(1+3+5+2+4+6)/6=7/2$, nên hai giá trị tháp bằng nhau.`)]},
      {prompt:b(String.raw`On four equiprobable states let G-blocks be {1,2},{3,4}, H trivial, and X=(1,7,2,10). Find E[X|G], its H-conditional mean, and E[X].`,String.raw`Trên bốn trạng thái đồng xác suất, G có khối {1,2},{3,4}, H tầm thường, X=(1,7,2,10). Tìm E[X|G], trung bình theo H và E[X].`),solution:[b(String.raw`The G-block means are $(1+7)/2=4$ and $(2+10)/2=6$, so $E[X|G]=(4,4,6,6)$.`,String.raw`Trung bình khối G là $(1+7)/2=4$ và $(2+10)/2=6$, nên $E[X|G]=(4,4,6,6)$.`),b(String.raw`Conditioning on H gives $(4+4+6+6)/4=5$.`,String.raw`Điều kiện theo H cho $(4+4+6+6)/4=5$.`),b(String.raw`The direct mean is $(1+7+2+10)/4=5$, verifying the same result.`,String.raw`Trung bình trực tiếp là $(1+7+2+10)/4=5$, xác minh cùng kết quả.`)]},
      {prompt:b(String.raw`On four equally likely states let G be the full sigma-field, H-blocks {1,2},{3,4}, and X=(2,6,1,9). Compute E[E[X|G]|H] and E[X|H].`,String.raw`Trên bốn trạng thái đồng xác suất, cho G là sigma-đại số đầy đủ, H có khối {1,2},{3,4}, X=(2,6,1,9). Tính E[E[X|G]|H] và E[X|H].`),solution:[b(String.raw`Since G is full, $E[X|G]=X=(2,6,1,9)$.`,String.raw`Vì G đầy đủ, $E[X|G]=X=(2,6,1,9)$.`),b(String.raw`Averaging within H-blocks gives means $(2+6)/2=4$ and $(1+9)/2=5$.`,String.raw`Lấy trung bình trong các khối H được $(2+6)/2=4$ và $(1+9)/2=5$.`),b(String.raw`Both expressions equal $(4,4,5,5)$, as H is the smaller sigma-field.`,String.raw`Hai biểu thức đều bằng $(4,4,5,5)$ vì H là sigma-đại số nhỏ hơn.`)]}
    ],
    reviewNote:'The primary partitions are nested, and each block has positive probability. The tower property is asserted up to a.s. equality, as conditional expectations are versions.',
    sourceIds:['p-mit6436']
  },
  'm2-w036-e2': {
    application:b('The tower property follows because the iterated conditional expectation has the defining integrals on every event in the smaller sigma-algebra.','Tính chất tháp suy ra vì kỳ vọng có điều kiện lặp có đúng tích phân định nghĩa trên mọi biến cố của sigma-đại số nhỏ hơn.'),
    formula:b(String.raw`$\mathcal H\subseteq\mathcal G\subseteq\mathcal F,\ X\in L^1:\quad E[E[X\mid\mathcal G]\mid\mathcal H]=E[X\mid\mathcal H]\text{ a.s.}$`,String.raw`$\mathcal H\subseteq\mathcal G\subseteq\mathcal F,\ X\in L^1:\quad E[E[X\mid\mathcal G]\mid\mathcal H]=E[X\mid\mathcal H]\text{ h.c.}$`),
    steps:[b(String.raw`Fix any A in H. Since A also lies in G, the inner defining identity gives $E[1_AE[X|G]]=E[1_AX]$.`,String.raw`Cố định A thuộc H. Vì A cũng thuộc G, đồng nhất thức trong cho $E[1_AE[X|G]]=E[1_AX]$.`),b(String.raw`The outer conditional expectation then gives $E[1_AE[E[X|G]|H]]=E[1_AE[X|G]]$.`,String.raw`Kỳ vọng có điều kiện bên ngoài cho $E[1_AE[E[X|G]|H]]=E[1_AE[X|G]]$.`),b(String.raw`Combining yields the required integral identity on every H-event.`,String.raw`Kết hợp hai đẳng thức cho đồng nhất thức tích phân cần thiết trên mọi biến cố H.`),b(String.raw`The iterated candidate is H-measurable and integrable; uniqueness of conditional expectation gives equality a.s.`,String.raw`Ứng viên lặp H-đo được và khả tích; tính duy nhất của kỳ vọng có điều kiện cho đẳng thức hầu chắc.`)],
    primarySolution:[b(String.raw`For every A in H⊆G, use the outer identity: $E[1_AE[E[X|G]|H]]=E[1_AE[X|G]]$.`,String.raw`Với mọi A thuộc H⊆G, dùng đồng nhất thức ngoài: $E[1_AE[E[X|G]|H]]=E[1_AE[X|G]]$.`),b(String.raw`The inner identity on the same A gives $E[1_AE[X|G]]=E[1_AX]$.`,String.raw`Đồng nhất thức trong trên cùng A cho $E[1_AE[X|G]]=E[1_AX]$.`),b(String.raw`Thus the iterated variable has the defining H-event integrals for E[X|H]. It is H-measurable and integrable.`,String.raw`Vậy biến lặp có đúng tích phân biến cố H định nghĩa E[X|H]. Nó H-đo được và khả tích.`),b(String.raw`Uniqueness up to a.s. equality proves $E[E[X|G]|H]=E[X|H]$.`,String.raw`Tính duy nhất tới đẳng thức hầu chắc chứng minh $E[E[X|G]|H]=E[X|H]$.`)],
    companions:[
      {prompt:b(String.raw`On six equally likely states, G-blocks are {1,2},{3,4},{5,6}, H-blocks are {1,2,3,4},{5,6}, and X=(0,4,2,6,3,9). Compute both conditional expectations in the tower identity.`,String.raw`Trên sáu trạng thái đồng xác suất, khối G là {1,2},{3,4},{5,6}, khối H là {1,2,3,4},{5,6}, X=(0,4,2,6,3,9). Tính hai kỳ vọng có điều kiện trong tính chất tháp.`),solution:[b(String.raw`Conditioning on G gives block means 2, 4, and 6: $E[X|G]=(2,2,4,4,6,6)$.`,String.raw`Điều kiện theo G cho trung bình khối 2,4,6: $E[X|G]=(2,2,4,4,6,6)$.`),b(String.raw`Averaging these over H-blocks gives 3 on the first four states and 6 on the last two.`,String.raw`Lấy trung bình trong các khối H cho 3 trên bốn trạng thái đầu và 6 trên hai trạng thái cuối.`),b(String.raw`Direct H-means are $(0+4+2+6)/4=3$ and $(3+9)/2=6$, so both sides equal $(3,3,3,3,6,6)$.`,String.raw`Trung bình H trực tiếp là $(0+4+2+6)/4=3$ và $(3+9)/2=6$, nên hai vế bằng $(3,3,3,3,6,6)$.`)]},
      {prompt:b(String.raw`Four equally likely outcomes have H-blocks {1,2},{3,4}, and G refines them into {1},{2},{3,4}. Let X=(2,8,1,5). Find E[X|G] and then condition on H.`,String.raw`Bốn kết quả đồng xác suất có khối H là {1,2},{3,4}, còn G tinh hơn thành {1},{2},{3,4}. Cho X=(2,8,1,5). Tìm E[X|G], rồi điều kiện theo H.`),solution:[b(String.raw`G-means are exact on singleton blocks and 3 on {3,4}: $E[X|G]=(2,8,3,3)$.`,String.raw`Trung bình G đúng bằng X trên khối đơn và bằng 3 trên {3,4}: $E[X|G]=(2,8,3,3)$.`),b(String.raw`Conditioning on H averages the first pair to 5 and the second pair of G-values to 3.`,String.raw`Điều kiện theo H lấy trung bình cặp đầu được 5 và cặp giá trị G sau được 3.`),b(String.raw`Direct H-means from X are also 5 and 3, giving $(5,5,3,3)$ both ways.`,String.raw`Trung bình H trực tiếp từ X cũng là 5 và 3, nên cả hai cách cho $(5,5,3,3)$.`)]},
      {prompt:b(String.raw`On a fair four-state space let G-blocks be {1,2},{3,4}, H trivial, and X=(−2,2,5,7). Compute E[X|G], its H-mean, and E[X|H].`,String.raw`Trên không gian bốn trạng thái đều, G có khối {1,2},{3,4}, H tầm thường, X=(−2,2,5,7). Tính E[X|G], trung bình theo H và E[X|H].`),solution:[b(String.raw`The block means are 0 and 6, so $E[X|G]=(0,0,6,6)$.`,String.raw`Trung bình khối là 0 và 6, nên $E[X|G]=(0,0,6,6)$.`),b(String.raw`The iterated mean is $(0+0+6+6)/4=3$.`,String.raw`Trung bình lặp là $(0+0+6+6)/4=3$.`),b(String.raw`The direct mean is $(−2+2+5+7)/4=3$, so the tower identity holds.`,String.raw`Trung bình trực tiếp là $(−2+2+5+7)/4=3$, nên tính chất tháp đúng.`)]}
    ],
    reviewNote:'The proof tests each H-event and then invokes uniqueness; integrability follows from X in L1 and the conditional-expectation construction.',
    sourceIds:['p-mit6436']
  },
  'm2-w036-e3': {
    application:b('Conditional expectation is an orthogonal projection: its residual has zero inner product with every square-integrable function measurable under G.','Kỳ vọng có điều kiện là phép chiếu trực giao: phần dư có tích vô hướng bằng không với mọi hàm bình phương khả tích đo được theo G.'),
    formula:b(String.raw`$X\in L^2,\ Z=E[X\mid G]\quad\Longrightarrow\quad E[(X-Z)H]=0\quad\forall H\in L^2(G).$`,String.raw`$X\in L^2,\ Z=E[X\mid G]\quad\Longrightarrow\quad E[(X-Z)H]=0\quad\forall H\in L^2(G).$`),
    steps:[b(String.raw`For a simple $H=\sum_jc_j1_{A_j}$ with A_j in G, each defining identity gives $E[1_{A_j}(X-Z)]=0$; summing yields orthogonality.`,String.raw`Với H đơn giản $H=\sum_jc_j1_{A_j}$, A_j thuộc G, mỗi đồng nhất thức cho $E[1_{A_j}(X-Z)]=0$; cộng lại được trực giao.`),b(String.raw`Conditional Jensen gives $E[Z^2]\le E[X^2]$, so $X-Z\in L^2$.`,String.raw`Jensen có điều kiện cho $E[Z^2]\le E[X^2]$, nên $X-Z\in L^2$.`),b(String.raw`Approximate any $H\in L^2(G)$ by G-measurable simple $H_m$ in L2.`,String.raw`Xấp xỉ mọi $H\in L^2(G)$ bằng hàm đơn G-đo được $H_m$ trong L2.`),b(String.raw`Cauchy–Schwarz bounds $|E[(X-Z)(H-H_m)]|\le\|X-Z\|_2\|H-H_m\|_2\to0$, passing the identity to H.`,String.raw`Cauchy–Schwarz chặn $|E[(X-Z)(H-H_m)]|\le\|X-Z\|_2\|H-H_m\|_2\to0$, truyền đồng nhất thức tới H.`)],
    primarySolution:[b(String.raw`For simple G-measurable H, write it as a finite sum of indicators of G-events.`,String.raw`Với H G-đo được đơn giản, viết thành tổng hữu hạn các hàm chỉ thị biến cố G.`),b(String.raw`The defining conditional-expectation identities on those events give $E[(X-Z)H]=0$.`,String.raw`Các đồng nhất thức định nghĩa kỳ vọng có điều kiện trên biến cố đó cho $E[(X-Z)H]=0$.`),b(String.raw`Jensen gives $E[Z^2]\le E[X^2]$, so the residual is in L2. Approximate general H in L2(G) by simple H_m.`,String.raw`Jensen cho $E[Z^2]\le E[X^2]$, nên phần dư thuộc L2. Xấp xỉ H tổng quát trong L2(G) bằng H_m đơn giản.`),b(String.raw`Cauchy–Schwarz makes the inner-product error tend to zero, proving $E[(X-Z)H]=0$.`,String.raw`Cauchy–Schwarz khiến sai số tích vô hướng tiến về không, chứng minh $E[(X-Z)H]=0$.`)],
    companions:[
      {prompt:b(String.raw`On four equally likely states, G-blocks are {1,2},{3,4}, X=(0,2,4,6), Z=(1,1,5,5). For H=(2,2,−3,−3), compute E[(X−Z)H].`,String.raw`Trên bốn trạng thái đồng xác suất, khối G là {1,2},{3,4}, X=(0,2,4,6), Z=(1,1,5,5). Với H=(2,2,−3,−3), tính E[(X−Z)H].`),solution:[b(String.raw`The residual is $X-Z=(-1,1,-1,1)$.`,String.raw`Phần dư là $X-Z=(-1,1,-1,1)$.`),b(String.raw`The products with H are $(−2,2,3,−3)$.`,String.raw`Các tích với H là $(−2,2,3,−3)$.`),b(String.raw`Their average is $(-2+2+3-3)/4=0$, as orthogonality predicts.`,String.raw`Trung bình là $(-2+2+3-3)/4=0$, đúng như trực giao dự đoán.`)]},
      {prompt:b(String.raw`On [0,1] with Lebesgue probability let G be trivial, X=U, Z=1/2, and H be the constant c. Compute E[(X−Z)H].`,String.raw`Trên [0,1] với xác suất Lebesgue, cho G tầm thường, X=U, Z=1/2, H là hằng c. Tính E[(X−Z)H].`),solution:[b(String.raw`The residual is $U-1/2$ and H is G-measurable and square-integrable.`,String.raw`Phần dư là $U-1/2$ và H G-đo được, bình phương khả tích.`),b(String.raw`Its mean is $\int_0^1(u-1/2)du=1/2-1/2=0$.`,String.raw`Trung bình là $\int_0^1(u-1/2)du=1/2-1/2=0$.`),b(String.raw`Therefore $E[(X-Z)H]=c\,E[U-1/2]=0$ for every finite c.`,String.raw`Do đó $E[(X-Z)H]=c\,E[U-1/2]=0$ với mọi c hữu hạn.`)]},
      {prompt:b(String.raw`On four equally likely states let G-blocks be {1,2},{3,4}, X=(1,5,2,8), and Z be its G-block means. Check orthogonality with H=(1,1,−2,−2).`,String.raw`Trên bốn trạng thái đồng xác suất, G có khối {1,2},{3,4}, X=(1,5,2,8), Z là trung bình khối G. Kiểm tra trực giao với H=(1,1,−2,−2).`),solution:[b(String.raw`The block means are 3 and 5, so $Z=(3,3,5,5)$ and residual $X-Z=(-2,2,-3,3)$.`,String.raw`Trung bình khối là 3 và 5, nên $Z=(3,3,5,5)$ và phần dư $X-Z=(-2,2,-3,3)$.`),b(String.raw`The products with H are $(-2,2,6,-6)$.`,String.raw`Các tích với H là $(-2,2,6,-6)$.`),b(String.raw`Their mean is zero, $(−2+2+6−6)/4=0$.`,String.raw`Trung bình bằng không, $(−2+2+6−6)/4=0$.`)]}
    ],
    reviewNote:'To extend beyond simple H, first use conditional Jensen to place Z in L2, then Cauchy–Schwarz passes the inner product through L2 approximation.',
    sourceIds:['p-mit6436']
  },
  'm2-w036-e4': {
    application:b('The conditional mean minimizes mean squared error among functions constant on the observed partition blocks.','Trung bình có điều kiện tối thiểu hóa sai số bình phương trung bình trong các hàm hằng theo khối quan sát.'),
    formula:b(String.raw`$E[(X-H)^2]=1+\frac{(a-1)^2+(b-5)^2}{2},\quad X=(0,2,4,6),\ H=(a,a,b,b)\text{ on four equiprobable states}.$`,String.raw`$E[(X-H)^2]=1+\frac{(a-1)^2+(b-5)^2}{2},\quad X=(0,2,4,6),\ H=(a,a,b,b)\text{ trên bốn trạng thái đồng xác suất}.$`),
    steps:[b(String.raw`Within block {1,2}, the mean is 1 and the within-block squared error at the mean is $((0-1)^2+(2-1)^2)/2=1$.`,String.raw`Trong khối {1,2}, trung bình là 1 và sai số bình phương nội khối tại trung bình là $((0-1)^2+(2-1)^2)/2=1$.`),b(String.raw`For a general fitted value a, the block mean squared error is $1+(a-1)^2$; on the second block it is $1+(b-5)^2$.`,String.raw`Với giá trị khớp a bất kỳ, sai số bình phương trung bình khối là $1+(a-1)^2$; ở khối hai là $1+(b-5)^2$.`),b(String.raw`Each block has probability 1/2; averaging gives the stated total risk.`,String.raw`Mỗi khối có xác suất 1/2; lấy trung bình cho rủi ro tổng đã nêu.`),b(String.raw`The squares are minimized at a=1,b=5, precisely the conditional block means.`,String.raw`Các bình phương đạt nhỏ nhất tại a=1,b=5, đúng bằng trung bình có điều kiện theo khối.`)],
    primarySolution:[b(String.raw`On the first block, the contribution to unconditional risk is $((0-a)^2+(2-a)^2)/4=((a-1)^2+1)/2$.`,String.raw`Trên khối đầu, đóng góp vào rủi ro vô điều kiện là $((0-a)^2+(2-a)^2)/4=((a-1)^2+1)/2$.`),b(String.raw`On the second block it is $((4-b)^2+(6-b)^2)/4=((b-5)^2+1)/2$.`,String.raw`Trên khối hai, đóng góp là $((4-b)^2+(6-b)^2)/4=((b-5)^2+1)/2$.`),b(String.raw`Adding yields $1+((a-1)^2+(b-5)^2)/2$.`,String.raw`Cộng lại được $1+((a-1)^2+(b-5)^2)/2$.`),b(String.raw`The unique minimizer is $(a,b)=(1,5)$, with minimum risk 1; these are the conditional means.`,String.raw`Điểm cực tiểu duy nhất là $(a,b)=(1,5)$, rủi ro nhỏ nhất bằng 1; đây là các trung bình có điều kiện.`)],
    companions:[
      {prompt:b(String.raw`Three equally likely observations are X=(1,3,5); G-blocks are {1,2} and {3}, and a G-measurable fit is H=(a,a,b). Derive its squared risk and minimizer.`,String.raw`Ba quan sát đồng xác suất X=(1,3,5); khối G là {1,2} và {3}, hàm khớp G-đo được H=(a,a,b). Suy ra rủi ro bình phương và điểm cực tiểu.`),solution:[b(String.raw`The first two squared errors contribute $((1-a)^2+(3-a)^2)/3=(2(a-2)^2+2)/3$.`,String.raw`Hai sai số bình phương đầu đóng góp $((1-a)^2+(3-a)^2)/3=(2(a-2)^2+2)/3$.`),b(String.raw`The singleton contributes $(5-b)^2/3$.`,String.raw`Nguyên tử đơn đóng góp $(5-b)^2/3$.`),b(String.raw`Thus risk is $2/3+(2/3)(a-2)^2+(1/3)(b-5)^2$, minimized at $(2,5)$.`,String.raw`Vậy rủi ro là $2/3+(2/3)(a-2)^2+(1/3)(b-5)^2$, nhỏ nhất tại $(2,5)$.`)]},
      {prompt:b(String.raw`Four equally likely measurements are X=(1,3,4,8) in blocks {1,2},{3,4}. For H=(a,a,b,b), derive risk and identify the conditional means.`,String.raw`Bốn phép đo đồng xác suất X=(1,3,4,8) trong các khối {1,2},{3,4}. Với H=(a,a,b,b), suy ra rủi ro và xác định trung bình có điều kiện.`),solution:[b(String.raw`The first block mean is 2 with within-block variance 1; its risk contribution is $((a-2)^2+1)/2$.`,String.raw`Khối đầu có trung bình 2, phương sai nội khối 1; đóng góp rủi ro là $((a-2)^2+1)/2$.`),b(String.raw`The second block mean is 6 with within-block variance 4; contribution is $((b-6)^2+4)/2$.`,String.raw`Khối hai có trung bình 6, phương sai nội khối 4; đóng góp là $((b-6)^2+4)/2$.`),b(String.raw`Total risk is $5/2+((a-2)^2+(b-6)^2)/2$, minimized at $(2,6)$.`,String.raw`Rủi ro tổng là $5/2+((a-2)^2+(b-6)^2)/2$, nhỏ nhất tại $(2,6)$.`)]},
      {prompt:b(String.raw`For three equally likely values X=(0,2,10), compare the constant fit c with the mean fit and derive the risk decomposition.`,String.raw`Với ba giá trị đồng xác suất X=(0,2,10), so sánh hàm khớp hằng c với hàm khớp trung bình và suy ra phân rã rủi ro.`),solution:[b(String.raw`The mean is $m=(0+2+10)/3=4$.`,String.raw`Trung bình là $m=(0+2+10)/3=4$.`),b(String.raw`Expand $E[(X-c)^2]=E[(X-m+m-c)^2]$; the cross term vanishes since $E[X-m]=0$.`,String.raw`Khai triển $E[(X-c)^2]=E[(X-m+m-c)^2]$; số hạng chéo triệt tiêu vì $E[X-m]=0$.`),b(String.raw`The variance is $(16+4+36)/3=56/3$, hence $E[(X-c)^2]=56/3+(c-4)^2$, minimized at c=4.`,String.raw`Phương sai là $(16+4+36)/3=56/3$, nên $E[(X-c)^2]=56/3+(c-4)^2$, nhỏ nhất tại c=4.`)]}
    ],
    reviewNote:'The risk expansion uses equal atom masses and completes squares around each block mean. The minimum risk is the within-block residual variance; fitted block means are unique.',
    sourceIds:['p-mit6436']
  },
  'm2-w036-e5': {
    application:b('A bounded quantity known from G can be pulled through conditional expectation by verifying the defining integrals on every G-event.','Đại lượng bị chặn đã biết theo G có thể đưa ra khỏi kỳ vọng có điều kiện bằng cách kiểm chứng tích phân định nghĩa trên mọi biến cố G.'),
    formula:b(String.raw`$H\text{ bounded and }\mathcal G\text{-measurable},\ X\in L^1:\quad E[HX\mid\mathcal G]=H\,E[X\mid\mathcal G]\text{ a.s.}$`,String.raw`$H\text{ bị chặn và }\mathcal G\text{-đo được},\ X\in L^1:\quad E[HX\mid\mathcal G]=H\,E[X\mid\mathcal G]\text{ h.c.}$`),
    steps:[b(String.raw`For simple H, partition into G-measurable level sets and apply the defining identity on each intersection with a test event A in G.`,String.raw`Với H đơn, phân hoạch theo các tập mức G-đo được rồi áp dụng đồng nhất thức định nghĩa trên giao từng tập với biến cố thử A thuộc G.`),b(String.raw`Approximate bounded H uniformly by bounded G-simple functions; boundedness ensures $HX\in L^1$.`,String.raw`Xấp xỉ đều H bị chặn bằng hàm đơn G-đo được bị chặn; tính bị chặn bảo đảm $HX\in L^1$.`),b(String.raw`The tested integrals converge, so both candidate sides have the same integral on every A in G.`,String.raw`Các tích phân thử hội tụ nên hai ứng viên có cùng tích phân trên mọi A thuộc G.`),b(String.raw`Both are G-measurable and integrable; uniqueness gives the claimed equality a.s.`,String.raw`Cả hai G-đo được và khả tích; tính duy nhất cho đẳng thức cần chứng minh hầu chắc.`)],
    primarySolution:[b(String.raw`For simple $H=\sum_jc_j1_{B_j}$, B_j in G, and A in G, compute $E[1_AHX]=\sum_jc_jE[1_{A\cap B_j}X]$.`,String.raw`Với H đơn $H=\sum_jc_j1_{B_j}$, B_j thuộc G, A thuộc G, tính $E[1_AHX]=\sum_jc_jE[1_{A\cap B_j}X]$.`),b(String.raw`Replace each term using the defining identity to get $\sum_jc_jE[1_{A\cap B_j}E[X|G]]=E[1_AH E[X|G]]$.`,String.raw`Thay mỗi số hạng bằng đồng nhất thức định nghĩa được $\sum_jc_jE[1_{A\cap B_j}E[X|G]]=E[1_AH E[X|G]]$.`),b(String.raw`Uniform simple approximation extends the tested identity to bounded H; boundedness and X in L1 make products integrable.`,String.raw`Xấp xỉ đơn đều mở rộng đồng nhất thức thử tới H bị chặn; tính bị chặn và X thuộc L1 làm tích khả tích.`),b(String.raw`The candidate $H E[X|G]$ is G-measurable and integrable because $E|E[X|G]|\le E|X|$; uniqueness proves the conditional identity.`,String.raw`Ứng viên $H E[X|G]$ G-đo được và khả tích vì $E|E[X|G]|\le E|X|$; tính duy nhất chứng minh đồng nhất thức có điều kiện.`)],
    companions:[
      {prompt:b(String.raw`On four equally likely states, G-blocks are {1,2},{3,4}, X=(0,2,4,6), and H=(2,2,−1,−1). Verify the pull-out identity using Z=E[X|G].`,String.raw`Trên bốn trạng thái đồng xác suất, khối G là {1,2},{3,4}, X=(0,2,4,6), H=(2,2,−1,−1). Kiểm tra đồng nhất thức đưa ra ngoài với Z=E[X|G].`),solution:[b(String.raw`The block means are 1 and 5, so $Z=(1,1,5,5)$.`,String.raw`Trung bình khối là 1 và 5, nên $Z=(1,1,5,5)$.`),b(String.raw`$E[HX]=(0+4-4-6)/4=-3/2$.`,String.raw`$E[HX]=(0+4-4-6)/4=-3/2$.`),b(String.raw`$E[HZ]=(2+2-5-5)/4=-3/2$, confirming equal conditional expectations on each G-block.`,String.raw`$E[HZ]=(2+2-5-5)/4=-3/2$, xác nhận kỳ vọng có điều kiện bằng nhau trên từng khối G.`)]},
      {prompt:b(String.raw`On [0,1] with U uniform, G=σ(U), X=U² and H=1_[0,1/3](U). Compute E[HX] and E[H E[X|G]].`,String.raw`Trên [0,1] với U đều, G=σ(U), X=U² và H=1_[0,1/3](U). Tính E[HX] và E[H E[X|G]].`),solution:[b(String.raw`Since X is G-measurable, $E[X|G]=X=U^2$.`,String.raw`Vì X G-đo được, $E[X|G]=X=U^2$.`),b(String.raw`Both products equal $U^2 1_{[0,1/3]}(U)$.`,String.raw`Hai tích đều bằng $U^2 1_{[0,1/3]}(U)$.`),b(String.raw`Integrating gives $\int_0^{1/3}u^2du=1/81$ on both sides.`,String.raw`Tích phân cho $\int_0^{1/3}u^2du=1/81$ ở cả hai vế.`)]},
      {prompt:b(String.raw`Six equally likely readings are X=(0,3,6,2,4,6), with G-blocks {1,2,3},{4,5,6}. Let H=(1,1,1,2,2,2). Compare E[HX] with E[H E[X|G]].`,String.raw`Sáu số đo đồng xác suất X=(0,3,6,2,4,6), khối G là {1,2,3},{4,5,6}. Cho H=(1,1,1,2,2,2). So sánh E[HX] và E[H E[X|G]].`),solution:[b(String.raw`The conditional block values are 3 and 4, so $Z=(3,3,3,4,4,4)$.`,String.raw`Giá trị có điều kiện theo khối là 3 và 4, nên $Z=(3,3,3,4,4,4)$.`),b(String.raw`$E[HZ]=(3+3+3+8+8+8)/6=11/2$.`,String.raw`$E[HZ]=(3+3+3+8+8+8)/6=11/2$.`),b(String.raw`$E[HX]=(0+3+6+4+8+12)/6=11/2$, equal to the pulled-out expression.`,String.raw`$E[HX]=(0+3+6+4+8+12)/6=11/2$, bằng biểu thức đưa H ra ngoài.`)]}
    ],
    reviewNote:'Bounded G-measurability makes H times X integrable; conditional Jensen gives integrability of H E[X|G]. The proof verifies candidate integrals before invoking uniqueness.',
    sourceIds:['p-mit6436']
  },
  'm2-w037-e1': {
    application:b(`Classify each sequence separately by pointwise behavior, tail probabilities, first moments, and distribution.`,`Phân loại từng dãy riêng theo hành vi từng điểm, xác suất đuôi, moment bậc nhất và phân phối.`),
    formula:b(String.raw`$X_n,X\text{ real random variables on a probability space}: X_n\to X\text{ a.s.}\Rightarrow X_n\to X\text{ in probability}\Rightarrow X_n\Rightarrow X,\quad L^1\Rightarrow\text{probability};\text{ converses may fail}.$`,String.raw`$X_n,X\text{ là các biến ngẫu nhiên thực trên không gian xác suất}: X_n\to X\text{ h.c.}\Rightarrow X_n\to X\text{ theo xác suất}\Rightarrow X_n\Rightarrow X,\quad L^1\Rightarrow\text{xác suất};\text{ chiều đảo có thể sai}.$`),
    steps:[b(String.raw`For $1_{[0,1/n]}(U)$ with U uniform on [0,1], $P(X_n=1)=E|X_n|=1/n$.`,String.raw`Với $1_{[0,1/n]}(U)$, U đều trên [0,1], $P(X_n=1)=E|X_n|=1/n$.`),b(String.raw`Every U>0 eventually leaves [0,1/n]; the exception U=0 is null, so convergence is a.s., in probability, and in L1.`,String.raw`Mọi U>0 cuối cùng rời [0,1/n]; ngoại lệ U=0 có xác suất không, nên hội tụ h.c., theo xác suất và L1.`),b(String.raw`For independent $1_{A_n}$ with $P(A_n)=1/n$, the same L1 error tends to zero, but Borel–Cantelli II gives infinitely many ones a.s.`,String.raw`Với $1_{A_n}$ độc lập, $P(A_n)=1/n$, sai số L1 cũng tiến về không, nhưng Borel–Cantelli II cho vô hạn số một h.c.`),b(String.raw`The constants $1/n$ converge everywhere and in L1, hence also in probability and distribution.`,String.raw`Các hằng số $1/n$ hội tụ tại mọi điểm và trong L1, do đó cũng theo xác suất và phân phối.`)],
    primarySolution:[b(String.raw`(i) $P(X_n=1)=1/n$ and $E|X_n|=1/n\to0$, giving probability and L1 convergence, and thus distribution convergence.`,String.raw`(i) $P(X_n=1)=1/n$ và $E|X_n|=1/n\to0$, nên hội tụ theo xác suất, L1 và do đó theo phân phối.`),b(String.raw`For each U>0 the indicator is eventually zero; U=0 is null. So (i) also converges a.s.`,String.raw`Với mỗi U>0, hàm chỉ thị cuối cùng bằng không; U=0 là tập không. Vậy (i) cũng hội tụ h.c.`),b(String.raw`(ii) The same exceedance and L1 calculations give probability, L1, and distribution convergence; independence and $\sum 1/n=\infty$ invoke Borel–Cantelli II, ruling out a.s. convergence.`,String.raw`(ii) Tính xác suất vượt và L1 tương tự cho hội tụ theo xác suất, L1, phân phối; tính độc lập và $\sum 1/n=\infty$ cho phép dùng Borel–Cantelli II, loại trừ hội tụ h.c.`),b(String.raw`(iii) Since $1/n\to0$ deterministically and $E|1/n|=1/n$, all four modes hold.`,String.raw`(iii) Vì $1/n\to0$ tất định và $E|1/n|=1/n$, cả bốn kiểu đều đúng.`)],
    companions:[
      {prompt:b(String.raw`On [0,1] with U uniform, let $Y_n=1_{[0,1/n^2]}(U)$. Classify convergence to zero in the four modes.`,String.raw`Trên [0,1] với U đều, đặt $Y_n=1_{[0,1/n^2]}(U)$. Phân loại hội tụ về không theo bốn kiểu.`),solution:[b(String.raw`For $0<\varepsilon<1$, $P(Y_n>\varepsilon)=E|Y_n|=1/n^2\to0$.`,String.raw`Với $0<\varepsilon<1$, $P(Y_n>\varepsilon)=E|Y_n|=1/n^2\to0$.`),b(String.raw`Each U>0 eventually exceeds $1/n^2$, while U=0 is null, so $Y_n\to0$ a.s.`,String.raw`Mỗi U>0 cuối cùng lớn hơn $1/n^2$, còn U=0 là tập không, nên $Y_n\to0$ h.c.`),b(String.raw`Thus it converges a.s., in probability, L1, and in distribution.`,String.raw`Vậy dãy hội tụ h.c., theo xác suất, L1 và theo phân phối.`)]},
      {prompt:b(String.raw`For independent indicators $V_n=1_{B_n}$ with $P(B_n)=1/(n+1)$, decide which modes of convergence to zero hold.`,String.raw`Với các chỉ thị độc lập $V_n=1_{B_n}$ có $P(B_n)=1/(n+1)$, xác định kiểu hội tụ nào về không đúng.`),solution:[b(String.raw`For $0<\varepsilon<1$, the exceedance probability and L1 error are both $1/(n+1)\to0$.`,String.raw`Với $0<\varepsilon<1$, xác suất vượt và sai số L1 đều bằng $1/(n+1)\to0$.`),b(String.raw`The harmonic sum $\sum_n1/(n+1)$ diverges; independence lets Borel–Cantelli II imply infinitely many $B_n$ a.s.`,String.raw`Tổng điều hòa $\sum_n1/(n+1)$ phân kỳ; tính độc lập cho Borel–Cantelli II suy ra vô hạn $B_n$ h.c.`),b(String.raw`Therefore probability, L1, and distribution convergence hold, but a.s. convergence to zero fails.`,String.raw`Do đó hội tụ theo xác suất, L1 và phân phối đúng, nhưng hội tụ h.c. về không sai.`)]},
      {prompt:b(String.raw`On a one-point probability space set $W_n=2/n$. Find its four convergence modes to zero and its L1 error.`,String.raw`Trên không gian xác suất một điểm, đặt $W_n=2/n$. Tìm bốn kiểu hội tụ về không và sai số L1.`),solution:[b(String.raw`The sole outcome has $W_n=2/n\to0$, so convergence is a.s.`,String.raw`Kết quả duy nhất có $W_n=2/n\to0$, nên hội tụ h.c.`),b(String.raw`For fixed epsilon, $|W_n|>\varepsilon$ eventually never occurs, giving probability convergence.`,String.raw`Với epsilon cố định, $|W_n|>\varepsilon$ cuối cùng không xảy ra, cho hội tụ xác suất.`),b(String.raw`The L1 error is $2/n\to0$; L1 implies probability convergence, and deterministic convergence also gives distribution convergence.`,String.raw`Sai số L1 là $2/n\to0$; L1 suy ra hội tụ xác suất, còn hội tụ tất định cũng cho hội tụ phân phối.`)]}
    ],
    reviewNote:`For the independent rare-event case, the L1 norm tends to zero while almost-sure convergence fails; these modes are compatible. At U=0 the first sequence stays one, but this is a null singleton.`,
    sourceIds:['p-mit6436']
  },
  'm2-w037-e2': {
    application:b(`Turn eventual pointwise closeness into decreasing tail events, then use continuity of probability from above.`,`Chuyển độ gần nhau cuối cùng từng điểm thành biến cố đuôi giảm, rồi dùng tính liên tục từ trên của xác suất.`),
    formula:b(String.raw`$X_n\to X\text{ a.s.},\ \varepsilon>0:\quad P(|X_n-X|>\varepsilon)\to0$ on a probability space.`,String.raw`$X_n\to X\text{ h.c.},\ \varepsilon>0:\quad P(|X_n-X|>\varepsilon)\to0$ trên không gian xác suất.`),
    steps:[b(String.raw`Let $B_n=\{|X_n-X|>\varepsilon\}$. A.s. convergence means almost every outcome lies in only finitely many B_n.`,String.raw`Đặt $B_n=\{|X_n-X|>\varepsilon\}$. Hội tụ h.c. nghĩa là hầu hết kết quả chỉ thuộc hữu hạn B_n.`),b(String.raw`The tail unions $C_m=\bigcup_{n\ge m}B_n$ decrease to the event that B_n occurs infinitely often.`,String.raw`Các hợp đuôi $C_m=\bigcup_{n\ge m}B_n$ giảm về biến cố B_n xảy ra vô hạn lần.`),b(String.raw`That intersection is null and $P(C_1)\le1$; continuity from above gives $P(C_m)\downarrow0$.`,String.raw`Giao đó có xác suất không và $P(C_1)\le1$; tính liên tục từ trên cho $P(C_m)\downarrow0$.`),b(String.raw`For n≥m, $B_n\subseteq C_m$, so $P(B_n)\le P(C_m)$; sending m to infinity proves the limit.`,String.raw`Với n≥m, $B_n\subseteq C_m$, nên $P(B_n)\le P(C_m)$; cho m tiến ra vô hạn suy ra giới hạn.`)],
    primarySolution:[b(String.raw`Fix epsilon and set $B_k=\{|X_k-X|>\varepsilon\}$ and $C_m=\cup_{k\ge m}B_k$.`,String.raw`Cố định epsilon, đặt $B_k=\{|X_k-X|>\varepsilon\}$ và $C_m=\cup_{k\ge m}B_k$.`),b(String.raw`The C_m decrease and $\cap_mC_m=\limsup_kB_k$ is null by a.s. convergence.`,String.raw`Các C_m giảm và $\cap_mC_m=\limsup_kB_k$ là tập không do hội tụ h.c.`),b(String.raw`Continuity from above applies because $P(C_1)\le1$, giving $P(C_m)\to0$.`,String.raw`Tính liên tục từ trên áp dụng vì $P(C_1)\le1$, cho $P(C_m)\to0$.`),b(String.raw`For n≥m, $P(B_n)\le P(C_m)$; hence the exceedance probabilities tend to zero.`,String.raw`Với n≥m, $P(B_n)\le P(C_m)$; vậy xác suất vượt ngưỡng tiến về không.`)],
    companions:[
      {prompt:b(String.raw`On [0,1] with Lebesgue probability let $Y_n(u)=u^n$. Prove a.s. convergence to zero and use the tail-event argument.`,String.raw`Trên [0,1] với xác suất Lebesgue, đặt $Y_n(u)=u^n$. Chứng minh hội tụ h.c. về không và dùng lập luận biến cố đuôi.`),solution:[b(String.raw`For u<1, $u^n\to0$; only u=1 fails, and that singleton has measure zero.`,String.raw`Với u<1, $u^n\to0$; chỉ u=1 thất bại và điểm này có độ đo không.`),b(String.raw`For fixed epsilon let $B_n=\{u:u^n>\varepsilon\}$ and $C_m=\cup_{n\ge m}B_n$; these tail unions decrease to a null set.`,String.raw`Với epsilon cố định đặt $B_n=\{u:u^n>\varepsilon\}$, $C_m=\cup_{n\ge m}B_n$; các hợp đuôi giảm về tập không.`),b(String.raw`Continuity from above gives $P(C_m)\to0$, and $P(B_m)\le P(C_m)$ proves convergence in probability.`,String.raw`Tính liên tục từ trên cho $P(C_m)\to0$, còn $P(B_m)\le P(C_m)$ chứng minh hội tụ theo xác suất.`)]},
      {prompt:b(String.raw`On four equally likely atoms let $Z_n=(1/n,0,0,0)$ and Z=0. For epsilon=1/10 compute the tail unions $C_m$.`,String.raw`Trên bốn nguyên tử đồng xác suất, đặt $Z_n=(1/n,0,0,0)$ và Z=0. Với epsilon=1/10, tính các hợp đuôi $C_m$.`),solution:[b(String.raw`The error event $B_n=\{|Z_n|>1/10\}$ is the first atom for n<10 and empty for n≥10.`,String.raw`Biến cố sai số $B_n=\{|Z_n|>1/10\}$ là nguyên tử đầu khi n<10 và rỗng khi n≥10.`),b(String.raw`Thus $C_m=\cup_{n\ge m}B_n$ is that atom for m≤9 and empty for m≥10.`,String.raw`Vì vậy $C_m=\cup_{n\ge m}B_n$ là nguyên tử ấy khi m≤9 và rỗng khi m≥10.`),b(String.raw`The tail probability becomes zero, so $P(B_n)\to0$ at this threshold; applying the argument to each epsilon proves probability convergence.`,String.raw`Xác suất đuôi trở thành không, nên $P(B_n)\to0$ ở ngưỡng này; áp dụng lập luận với mọi epsilon cho hội tụ xác suất.`)]},
      {prompt:b(String.raw`For deterministic $Q_n=1/n$, identify $B_n=\{Q_n>\varepsilon\}$ and its tail union for fixed epsilon>0.`,String.raw`Với $Q_n=1/n$ tất định, xác định $B_n=\{Q_n>\varepsilon\}$ và hợp đuôi với epsilon>0 cố định.`),solution:[b(String.raw`$B_n=\Omega$ when $n<1/\varepsilon$ and is empty otherwise.`,String.raw`$B_n=\Omega$ khi $n<1/\varepsilon$ và rỗng nếu ngược lại.`),b(String.raw`The tail union $C_m=\cup_{n\ge m}B_n$ is Ω until m passes the last index with $1/n>\varepsilon$, then empty.`,String.raw`Hợp đuôi $C_m=\cup_{n\ge m}B_n$ bằng Ω đến khi m vượt chỉ số cuối có $1/n>\varepsilon$, rồi rỗng.`),b(String.raw`So $P(C_m)$ eventually falls to zero, and the tail inclusion bounds each later $P(B_n)$ by it.`,String.raw`Vậy $P(C_m)$ cuối cùng giảm về không, và bao hàm đuôi chặn mỗi $P(B_n)$ về sau bởi nó.`)]}
    ],
    reviewNote:`Continuity from above needs decreasing events and a finite first measure; probability measures satisfy this. The current-error-to-tail-union inclusion is what returns the tail limit to each original probability.`,
    sourceIds:['p-mit6436']
  },
  'm2-w037-e3': {
    application:b(`Rare independent events can yield indicators that are usually zero but have infinitely many ones almost surely.`,`Biến cố độc lập hiếm có thể cho các chỉ thị thường bằng không nhưng có vô hạn số một hầu chắc.`),
    formula:b(String.raw`$X_n=1_{A_n},\ A_n\text{ independent},\ P(A_n)=1/n:\quad X_n\to_P0\text{ but not a.s.}$`,String.raw`$X_n=1_{A_n},\ A_n\text{ độc lập},\ P(A_n)=1/n:\quad X_n\to_P0\text{ nhưng không h.c.}$`),
    steps:[b(String.raw`For 0<epsilon<1 the exceedance event is A_n, with probability 1/n→0; for epsilon≥1 it is empty.`,String.raw`Với 0<epsilon<1, biến cố vượt ngưỡng là A_n, xác suất 1/n→0; với epsilon≥1 thì rỗng.`),b(String.raw`The probability sum diverges, and independence supplies the second hypothesis of Borel–Cantelli II.`,String.raw`Tổng xác suất phân kỳ và tính độc lập cung cấp giả thiết thứ hai của Borel–Cantelli II.`),b(String.raw`Hence A_n occurs infinitely often a.s.; the indicators have infinitely many ones, so cannot converge to zero a.s.`,String.raw`Vì vậy A_n xảy ra vô hạn lần h.c.; các chỉ thị có vô hạn số một nên không hội tụ về không h.c.`)],
    primarySolution:[b(String.raw`For 0<epsilon<1, $P(|X_n|>\varepsilon)=1/n\to0$; for epsilon≥1 this probability is zero.`,String.raw`Với 0<epsilon<1, $P(|X_n|>\varepsilon)=1/n\to0$; với epsilon≥1 xác suất bằng không.`),b(String.raw`Since the independent events have $\sum_nP(A_n)=\sum_n1/n=\infty$, Borel–Cantelli II gives $P(A_n\text{ i.o.})=1$.`,String.raw`Vì các biến cố độc lập có $\sum_nP(A_n)=\sum_n1/n=\infty$, Borel–Cantelli II cho $P(A_n\text{ i.o.})=1$.`),b(String.raw`Infinitely many values X_n equal one almost surely, ruling out convergence to zero a.s.; probability convergence still holds.`,String.raw`Vô hạn giá trị X_n bằng một hầu chắc, loại trừ hội tụ về không h.c.; hội tụ theo xác suất vẫn đúng.`)],
    companions:[
      {prompt:b(String.raw`For independent $R_n=1_{B_n}$ with $P(B_n)=1/(n+2)$, decide probability and almost-sure convergence to zero.`,String.raw`Với $R_n=1_{B_n}$ độc lập có $P(B_n)=1/(n+2)$, xác định hội tụ xác suất và h.c. về không.`),solution:[b(String.raw`For 0<epsilon<1, $P(R_n>\varepsilon)=1/(n+2)\to0$; for epsilon≥1 it is zero.`,String.raw`Với 0<epsilon<1, $P(R_n>\varepsilon)=1/(n+2)\to0$; với epsilon≥1 bằng không.`),b(String.raw`The shifted harmonic series diverges, and independence allows Borel–Cantelli II.`,String.raw`Chuỗi điều hòa dịch phân kỳ và tính độc lập cho phép dùng Borel–Cantelli II.`),b(String.raw`Thus B_n occurs infinitely often a.s.; R_n converges in probability but not a.s. to zero.`,String.raw`Vậy B_n xảy ra vô hạn lần h.c.; R_n hội tụ theo xác suất nhưng không h.c. về không.`)]},
      {prompt:b(String.raw`For independent indicators $S_n=1_{C_n}$ with $P(C_n)=1/n^2$, determine whether convergence to zero is in probability and almost surely.`,String.raw`Với các chỉ thị độc lập $S_n=1_{C_n}$ có $P(C_n)=1/n^2$, xác định hội tụ về không theo xác suất và h.c.`),solution:[b(String.raw`The exceedance probability is $1/n^2$ for 0<epsilon<1 and tends to zero.`,String.raw`Xác suất vượt ngưỡng là $1/n^2$ khi 0<epsilon<1 và tiến về không.`),b(String.raw`Because $\sum_n1/n^2<\infty$, Borel–Cantelli I implies only finitely many C_n occur; independence is not needed here.`,String.raw`Vì $\sum_n1/n^2<\infty$, Borel–Cantelli I cho chỉ hữu hạn C_n xảy ra; ở đây không cần độc lập.`),b(String.raw`The indicators are eventually zero a.s., so both probability and almost-sure convergence hold.`,String.raw`Các chỉ thị cuối cùng bằng không h.c., nên cả hội tụ xác suất và h.c. đều đúng.`)]},
      {prompt:b(String.raw`Let every event D_n equal a fixed D with $P(D)=1/3$ and $T_n=1_{D_n}$. Does T_n converge to zero in probability or almost surely?`,String.raw`Cho mọi D_n bằng một D cố định có $P(D)=1/3$ và $T_n=1_{D_n}$. T_n có hội tụ về không theo xác suất hoặc h.c. không?`),solution:[b(String.raw`For 0<epsilon<1, $P(|T_n|>\varepsilon)=1/3$ for every n, so probability convergence fails.`,String.raw`Với 0<epsilon<1, $P(|T_n|>\varepsilon)=1/3$ với mọi n, nên hội tụ xác suất thất bại.`),b(String.raw`On D the sequence is constantly one; on Dᶜ it is constantly zero, so its pointwise limit is 1_D.`,String.raw`Trên D dãy luôn bằng một; trên Dᶜ luôn bằng không, nên giới hạn từng điểm là 1_D.`),b(String.raw`Since $P(D)=1/3>0$, this limit differs from zero on positive mass, so a.s. convergence to zero fails too.`,String.raw`Vì $P(D)=1/3>0$, giới hạn khác không trên khối lượng dương, nên hội tụ h.c. về không cũng thất bại.`)]}
    ],
    reviewNote:`Borel–Cantelli II needs independence and a divergent sum; both are stated in the primary. The square-summable companion correctly uses lemma I without independence.`,
    sourceIds:['p-mit6436']
  },
  'm2-w037-e4': {
    application:b(`Apply Markov’s inequality to the nonnegative pth power of the error.`,`Áp dụng bất đẳng thức Markov cho lũy thừa p không âm của sai số.`),
    formula:b(String.raw`$p>0,\ E|X_n-X|^p<\infty,\ \varepsilon>0:\quad P(|X_n-X|>\varepsilon)\le E|X_n-X|^p/\varepsilon^p.$`,String.raw`$p>0,\ E|X_n-X|^p<\infty,\ \varepsilon>0:\quad P(|X_n-X|>\varepsilon)\le E|X_n-X|^p/\varepsilon^p.$`),
    steps:[b(String.raw`Set $W=|X_n-X|^p\ge0$ and the positive threshold $a=\varepsilon^p$.`,String.raw`Đặt $W=|X_n-X|^p\ge0$ và ngưỡng dương $a=\varepsilon^p$.`),b(String.raw`The error event $|X_n-X|>\varepsilon$ is exactly the event W>a.`,String.raw`Biến cố sai số $|X_n-X|>\varepsilon$ đúng bằng biến cố W>a.`),b(String.raw`Markov gives $P(W>a)\le E[W]/a=E|X_n-X|^p/\varepsilon^p$.`,String.raw`Markov cho $P(W>a)\le E[W]/a=E|X_n-X|^p/\varepsilon^p$.`),b(String.raw`If the pth error moment tends to zero, this bound tends to zero for each fixed epsilon, proving probability convergence.`,String.raw`Nếu moment sai số bậc p tiến về không, chặn này tiến về không với mỗi epsilon cố định, chứng minh hội tụ theo xác suất.`)],
    primarySolution:[b(String.raw`Finite expectation and nonnegativity let us apply Markov to $W=|X_n-X|^p$.`,String.raw`Kỳ vọng hữu hạn và tính không âm cho phép áp dụng Markov cho $W=|X_n-X|^p$.`),b(String.raw`On $\{|X_n-X|>\varepsilon\}$, W exceeds $\varepsilon^p$, yielding $P(|X_n-X|>\varepsilon)\le E[W]/\varepsilon^p$.`,String.raw`Trên $\{|X_n-X|>\varepsilon\}$, W vượt $\varepsilon^p$, suy ra $P(|X_n-X|>\varepsilon)\le E[W]/\varepsilon^p$.`),b(String.raw`This is the claimed inequality. If $E|X_n-X|^p\to0$, fix epsilon and let n grow; the probability tends to zero.`,String.raw`Đây là bất đẳng thức cần chứng minh. Nếu $E|X_n-X|^p\to0$, cố định epsilon rồi cho n tăng; xác suất tiến về không.`),b(String.raw`Thus convergence in Lp (with the pth error moment tending to zero) implies convergence in probability.`,String.raw`Vậy hội tụ Lp (moment sai số bậc p tiến về không) suy ra hội tụ theo xác suất.`)],
    companions:[
      {prompt:b(String.raw`Suppose $E|Y_n|^3=8/n$. Bound $P(|Y_n|>1/2)$ and show $Y_n\to_P0$.`,String.raw`Giả sử $E|Y_n|^3=8/n$. Chặn $P(|Y_n|>1/2)$ và chứng minh $Y_n\to_P0$.`),solution:[b(String.raw`With p=3 and epsilon=1/2, the bound is $(8/n)/(1/2)^3=64/n$.`,String.raw`Với p=3, epsilon=1/2, chặn bằng $(8/n)/(1/2)^3=64/n$.`),b(String.raw`This bound tends to zero, though for small n it may exceed one and remain only a valid upper bound.`,String.raw`Chặn này tiến về không, dù với n nhỏ có thể lớn hơn một và chỉ còn là chặn trên hợp lệ.`),b(String.raw`For any fixed epsilon>0, Markov gives $P(|Y_n|>\varepsilon)\le8/(n\varepsilon^3)\to0$, proving convergence in probability.`,String.raw`Với epsilon>0 cố định, Markov cho $P(|Y_n|>\varepsilon)\le8/(n\varepsilon^3)\to0$, chứng minh hội tụ theo xác suất.`)]},
      {prompt:b(String.raw`If $E|Z_n-Z|^2\le9/n$, bound $P(|Z_n-Z|>0.3)$ and infer convergence in probability.`,String.raw`Nếu $E|Z_n-Z|^2\le9/n$, chặn $P(|Z_n-Z|>0.3)$ và suy ra hội tụ theo xác suất.`),solution:[b(String.raw`Here p=2 and $\varepsilon^2=0.09$.`,String.raw`Ở đây p=2 và $\varepsilon^2=0.09$.`),b(String.raw`Markov yields $P(|Z_n-Z|>0.3)\le(9/n)/0.09=100/n$.`,String.raw`Markov cho $P(|Z_n-Z|>0.3)\le(9/n)/0.09=100/n$.`),b(String.raw`For any fixed threshold epsilon>0, the same bound is $9/(n\varepsilon^2)\to0$, so $Z_n\to_PZ$.`,String.raw`Với ngưỡng epsilon>0 cố định bất kỳ, chặn tương tự là $9/(n\varepsilon^2)\to0$, nên $Z_n\to_PZ$.`)]},
      {prompt:b(String.raw`On a fair two-point space let $Q_n=(1/n,-1/n)$. Compute $E|Q_n|^p$ for p>0 and verify the Markov conclusion.`,String.raw`Trên không gian hai điểm đều, đặt $Q_n=(1/n,-1/n)$. Tính $E|Q_n|^p$ với p>0 và kiểm tra kết luận Markov.`),solution:[b(String.raw`At each atom $|Q_n|=1/n$, hence $E|Q_n|^p=1/n^p$.`,String.raw`Ở mỗi nguyên tử $|Q_n|=1/n$, nên $E|Q_n|^p=1/n^p$.`),b(String.raw`For fixed epsilon, the bound is $P(|Q_n|>\varepsilon)\le1/(n^p\varepsilon^p)$.`,String.raw`Với epsilon cố định, chặn là $P(|Q_n|>\varepsilon)\le1/(n^p\varepsilon^p)$.`),b(String.raw`If $1/n\le\varepsilon$, the actual event is empty; the bound may be loose but tends to zero, verifying convergence in probability.`,String.raw`Nếu $1/n\le\varepsilon$, biến cố thực rỗng; chặn có thể lỏng nhưng tiến về không, xác minh hội tụ theo xác suất.`)]}
    ],
    reviewNote:`Markov requires a nonnegative integrable variable and a strictly positive threshold. The implication works for every p>0; in the usual Lp space notation one often assumes p≥1.`,
    sourceIds:['p-mit6436']
  },
  'm2-w037-e5': {
    application:b(`Two probability limits of one sequence agree almost surely by the triangle inequality and countable thresholds.`,`Hai giới hạn xác suất của cùng một dãy bằng nhau hầu chắc nhờ bất đẳng thức tam giác và ngưỡng đếm được.`),
    formula:b(String.raw`$X_n,X,Y\text{ real random variables},\ X_n\to_PX,\ X_n\to_PY,\ \varepsilon>0:\quad P(|X-Y|>\varepsilon)\le P(|X-X_n|>\varepsilon/2)+P(|X_n-Y|>\varepsilon/2).$`,String.raw`$X_n,X,Y\text{ là các biến ngẫu nhiên thực},\ X_n\to_PX,\ X_n\to_PY,\ \varepsilon>0:\quad P(|X-Y|>\varepsilon)\le P(|X-X_n|>\varepsilon/2)+P(|X_n-Y|>\varepsilon/2).$`),
    steps:[b(String.raw`The triangle inequality gives $|X-Y|\le|X-X_n|+|X_n-Y|$.`,String.raw`Bất đẳng thức tam giác cho $|X-Y|\le|X-X_n|+|X_n-Y|$.`),b(String.raw`If both deviations were at most epsilon/2, their sum would be at most epsilon; hence the event on the left is contained in the union of the two deviation events.`,String.raw`Nếu cả hai độ lệch không quá epsilon/2, tổng không quá epsilon; vì vậy biến cố trái nằm trong hợp hai biến cố độ lệch.`),b(String.raw`Take probabilities and let n grow. Each probability on the right tends to zero by the two convergence assumptions.`,String.raw`Lấy xác suất rồi cho n tăng. Mỗi xác suất bên phải tiến về không theo hai giả thiết hội tụ.`),b(String.raw`For epsilon=1/k, each event $\{|X-Y|>1/k\}$ is null. Their union is $\{X\ne Y\}$, so X=Y a.s.`,String.raw`Với epsilon=1/k, mỗi biến cố $\{|X-Y|>1/k\}$ là tập không. Hợp của chúng là $\{X\ne Y\}$, nên X=Y h.c.`)],
    primarySolution:[b(String.raw`For fixed epsilon, triangle inequality gives $\{|X-Y|>\varepsilon\}\subseteq\{|X-X_n|>\varepsilon/2\}\cup\{|X_n-Y|>\varepsilon/2\}$.`,String.raw`Với epsilon cố định, tam giác cho $\{|X-Y|>\varepsilon\}\subseteq\{|X-X_n|>\varepsilon/2\}\cup\{|X_n-Y|>\varepsilon/2\}$.`),b(String.raw`The union bound makes the probability of the left event no larger than the sum of the two right probabilities.`,String.raw`Chặn hợp làm xác suất biến cố trái không vượt tổng hai xác suất bên phải.`),b(String.raw`Let n→∞; both right probabilities vanish, so $P(|X-Y|>\varepsilon)=0$.`,String.raw`Cho n→∞; hai xác suất bên phải mất đi, nên $P(|X-Y|>\varepsilon)=0$.`),b(String.raw`Use epsilon=1/k for k≥1. Countable subadditivity gives $P(X\ne Y)=0$, hence equality almost surely.`,String.raw`Dùng epsilon=1/k với k≥1. Tính bán cộng đếm được cho $P(X\ne Y)=0$, tức bằng nhau hầu chắc.`)],
    companions:[
      {prompt:b(String.raw`On two equally likely atoms let $U_n=(1/n,0)$ and U=V=(0,0). Verify that both candidates are probability limits.`,String.raw`Trên hai nguyên tử đồng xác suất, đặt $U_n=(1/n,0)$ và U=V=(0,0). Xác minh cả hai ứng viên là giới hạn theo xác suất.`),solution:[b(String.raw`For fixed epsilon>0, once $1/n\le\varepsilon$, $|U_n-U|>\varepsilon$ never occurs.`,String.raw`Với epsilon>0 cố định, khi $1/n\le\varepsilon$, $|U_n-U|>\varepsilon$ không xảy ra.`),b(String.raw`Because V=U, the same exceedance calculation holds for V.`,String.raw`Vì V=U, phép tính xác suất vượt tương tự đúng với V.`),b(String.raw`Thus both are probability limits and agree everywhere, consistent with uniqueness.`,String.raw`Vậy cả hai là giới hạn xác suất và bằng nhau mọi nơi, phù hợp tính duy nhất.`)]},
      {prompt:b(String.raw`On three equally likely atoms let $R_n=(1/n,1/n,1/n)$, R=0, and S=(0,0,1). Which candidate is a probability limit?`,String.raw`Trên ba nguyên tử đồng xác suất, đặt $R_n=(1/n,1/n,1/n)$, R=0, S=(0,0,1). Ứng viên nào là giới hạn xác suất?`),solution:[b(String.raw`The distance from R_n to R is $1/n$ at every atom, so R is a probability limit.`,String.raw`Khoảng cách R_n tới R bằng $1/n$ ở mọi nguyên tử, nên R là giới hạn xác suất.`),b(String.raw`On the third atom, the distance to S tends to one; at threshold 1/2 the deviation probability is at least 1/3 eventually.`,String.raw`Trên nguyên tử thứ ba, khoảng cách tới S tiến về một; ở ngưỡng 1/2 xác suất lệch cuối cùng ít nhất 1/3.`),b(String.raw`So S is not a probability limit; there is only one valid candidate, as uniqueness predicts.`,String.raw`Vậy S không là giới hạn xác suất; chỉ có một ứng viên đúng, như tính duy nhất dự đoán.`)]},
      {prompt:b(String.raw`On two equally likely atoms let $T_n=(0,1/n)$, T=(0,0), W=(1,0). Prove convergence in probability to T and rule out W.`,String.raw`Trên hai nguyên tử đồng xác suất, đặt $T_n=(0,1/n)$, T=(0,0), W=(1,0). Chứng minh hội tụ xác suất về T và loại W.`),solution:[b(String.raw`The distance to T is 1/n on both atoms, so every fixed epsilon exceedance is eventually empty.`,String.raw`Khoảng cách tới T là 1/n ở cả hai nguyên tử, nên biến cố vượt ngưỡng epsilon cố định cuối cùng rỗng.`),b(String.raw`The distance to W is at least one on the first atom for every n.`,String.raw`Khoảng cách tới W ít nhất bằng một ở nguyên tử đầu với mọi n.`),b(String.raw`At threshold 1/2 this event has probability at least 1/2, so convergence to W in probability fails.`,String.raw`Ở ngưỡng 1/2 biến cố này có xác suất ít nhất 1/2, nên hội tụ xác suất về W thất bại.`)]}
    ],
    reviewNote:`The event inclusion and union bound apply for each fixed epsilon; the a.s. conclusion uses countably many thresholds 1/k. The companions check both equal and unequal limit candidates directly.`,
    sourceIds:['p-mit6436']
  },

  'm2-w038-e1': {
    application:b(`Uniform integrability asks whether expected absolute mass beyond a threshold vanishes uniformly over the whole family.`,`Khả tích đồng đều hỏi liệu kỳ vọng trị tuyệt đối phía ngoài ngưỡng có cùng tiến về không trên cả họ hay không.`),
    formula:b(String.raw`$\{X_n\}\text{ UI}\iff\lim_{K\to\infty}\sup_nE[|X_n|1_{\{|X_n|>K\}}]=0.$`,String.raw`$\{X_n\}\text{ UI}\iff\lim_{K\to\infty}\sup_nE[|X_n|1_{\{|X_n|>K\}}]=0.$`),
    steps:[b(String.raw`If $|X_n|\le3$ for every n, then for K≥3 the event $|X_n|>K$ is empty, making every tail expectation zero.`,String.raw`Nếu $|X_n|\le3$ với mọi n, khi K≥3 biến cố $|X_n|>K$ rỗng nên mọi kỳ vọng đuôi bằng không.`),b(String.raw`For $X_n=n1_{(0,1/n)}(U)$ with U uniform on (0,1), when n>K the tail is the interval (0,1/n).`,String.raw`Với $X_n=n1_{(0,1/n)}(U)$, U đều trên (0,1), khi n>K phần đuôi là khoảng (0,1/n).`),b(String.raw`That tail expectation equals $n\cdot(1/n)=1$; if n≤K it is zero.`,String.raw`Kỳ vọng đuôi đó bằng $n\cdot(1/n)=1$; nếu n≤K thì bằng không.`),b(String.raw`Thus the supremum is 1 for every K and fails to tend to zero, so this spike family is not UI.`,String.raw`Vậy supremum bằng 1 với mọi K và không tiến về không, nên họ đỉnh này không UI.`)],
    primarySolution:[b(String.raw`For the bounded family, $|X_n|\le3$ implies $1_{\{|X_n|>K\}}=0$ whenever K≥3, so its tail supremum is zero.`,String.raw`Với họ bị chặn, $|X_n|\le3$ cho $1_{\{|X_n|>K\}}=0$ khi K≥3, nên supremum đuôi bằng không.`),b(String.raw`For a fixed K choose an integer n>K. Then $X_n=n$ on an interval of measure 1/n and is zero elsewhere.`,String.raw`Với K cố định chọn số nguyên n>K. Khi đó $X_n=n$ trên khoảng độ đo 1/n và bằng không ở nơi khác.`),b(String.raw`Its tail expectation is $E[|X_n|1_{\{|X_n|>K\}}]=n(1/n)=1$, so the supremum over n is at least one.`,String.raw`Kỳ vọng đuôi là $E[|X_n|1_{\{|X_n|>K\}}]=n(1/n)=1$, nên supremum theo n ít nhất bằng một.`),b(String.raw`For every n the tail term is at most $E|X_n|=1$, so the supremum equals one for every K; the family is not UI.`,String.raw`Với mọi n, số hạng đuôi không quá $E|X_n|=1$, nên supremum bằng một với mọi K; họ không UI.`)],
    companions:[
      {prompt:b(String.raw`On a probability space suppose $Y_n=2\sin(nU)$ for any random U. Compute a threshold beyond which the family is UI and its tail supremum.`,String.raw`Trên không gian xác suất, cho $Y_n=2\sin(nU)$ với U ngẫu nhiên bất kỳ. Tìm ngưỡng để họ UI và tính supremum đuôi.`),solution:[b(String.raw`Since $|\sin(nU)|\le1$, we have $|Y_n|\le2$ for every n and every outcome.`,String.raw`Vì $|\sin(nU)|\le1$, nên $|Y_n|\le2$ với mọi n và mọi kết quả.`),b(String.raw`For K≥2, the strict tail event $|Y_n|>K$ is empty for every n.`,String.raw`Với K≥2, biến cố đuôi nghiêm ngặt $|Y_n|>K$ rỗng với mọi n.`),b(String.raw`Therefore the tail supremum is zero for K≥2 and the family is UI.`,String.raw`Do đó supremum đuôi bằng không khi K≥2 và họ là UI.`)]},
      {prompt:b(String.raw`On a four-state space let $Z_n=(−2,0,2,−1)$ for every n. Calculate the tail supremum for K≥2 and decide UI.`,String.raw`Trên không gian bốn trạng thái, cho $Z_n=(−2,0,2,−1)$ với mọi n. Tính supremum đuôi khi K≥2 và quyết định UI.`),solution:[b(String.raw`Every coordinate has absolute value at most 2.`,String.raw`Mọi tọa độ có trị tuyệt đối không quá 2.`),b(String.raw`At K≥2 no coordinate satisfies $|Z_n|>K$, so each tail expectation is zero.`,String.raw`Khi K≥2 không tọa độ nào thỏa $|Z_n|>K$, nên mỗi kỳ vọng đuôi bằng không.`),b(String.raw`The supremum is zero for all K≥2; this bounded family is uniformly integrable.`,String.raw`Supremum bằng không với mọi K≥2; họ bị chặn này khả tích đồng đều.`)]},
      {prompt:b(String.raw`On (0,1) with U uniform set $W_n=3n1_{(0,1/(3n))}(U)$. Compute its UI tail supremum for arbitrary K>0.`,String.raw`Trên (0,1) với U đều, đặt $W_n=3n1_{(0,1/(3n))}(U)$. Tính supremum đuôi UI với K>0 bất kỳ.`),solution:[b(String.raw`Choose an integer n>K/3; then the nonzero value 3n exceeds K on a set of measure $1/(3n)$.`,String.raw`Chọn số nguyên n>K/3; khi đó giá trị khác không 3n vượt K trên tập độ đo $1/(3n)$.`),b(String.raw`The corresponding tail expectation is $3n\cdot1/(3n)=1$, while every tail expectation is at most $E|W_n|=1$.`,String.raw`Kỳ vọng đuôi tương ứng là $3n\cdot1/(3n)=1$, còn mọi kỳ vọng đuôi không quá $E|W_n|=1$.`),b(String.raw`The supremum is exactly one for every K, so the family is not UI.`,String.raw`Supremum đúng bằng một với mọi K, nên họ không UI.`)]}
    ],
    reviewNote:`For the spike, the supremum is exactly one: a chosen n>K attains one and no tail expectation can exceed the full mean one. Bounded families have identically zero tails beyond their common bound.`,
    sourceIds:['p-mit6436']
  },
  'm2-w038-e2': {
    application:b(`Split the absolute error into the event where it is at most epsilon and its complement, where boundedness controls it.`,`Tách sai số tuyệt đối thành biến cố sai số không quá epsilon và phần bù, nơi tính bị chặn khống chế nó.`),
    formula:b(String.raw`$|U_n|,|U|\le K,\ U_n\to_PU,\ 0\le K<\infty,\ \varepsilon>0:\quad E|U_n-U|\le\varepsilon+2K\,P(|U_n-U|>\varepsilon).$`,String.raw`$|U_n|,|U|\le K,\ U_n\to_PU,\ 0\le K<\infty,\ \varepsilon>0:\quad E|U_n-U|\le\varepsilon+2K\,P(|U_n-U|>\varepsilon).$`),
    steps:[b(String.raw`On $G_n=\{|U_n-U|\le\varepsilon\}$, the contribution $E[|U_n-U|1_{G_n}]$ is at most epsilon.`,String.raw`Trên $G_n=\{|U_n-U|\le\varepsilon\}$, đóng góp $E[|U_n-U|1_{G_n}]$ không quá epsilon.`),b(String.raw`On $G_n^c$, the triangle inequality and the two K-bounds give $|U_n-U|\le2K$.`,String.raw`Trên $G_n^c$, bất đẳng thức tam giác và hai chặn K cho $|U_n-U|\le2K$.`),b(String.raw`Thus the complementary contribution is at most $2K P(G_n^c)$, yielding the stated inequality.`,String.raw`Vì vậy đóng góp phần bù không quá $2K P(G_n^c)$, cho bất đẳng thức đã nêu.`),b(String.raw`For fixed epsilon, convergence in probability sends the probability term to zero; then let epsilon decrease to zero to obtain $E|U_n-U|\to0$.`,String.raw`Với epsilon cố định, hội tụ xác suất làm số hạng xác suất tiến về không; sau đó cho epsilon giảm về không để được $E|U_n-U|\to0$.`)],
    primarySolution:[b(String.raw`Let $G_n=\{|U_n-U|\le\varepsilon\}$. The expectation on G_n is at most $\varepsilon P(G_n)\le\varepsilon$.`,String.raw`Đặt $G_n=\{|U_n-U|\le\varepsilon\}$. Kỳ vọng trên G_n không quá $\varepsilon P(G_n)\le\varepsilon$.`),b(String.raw`On its complement, $|U_n-U|\le|U_n|+|U|\le2K$, so the other part is at most $2K P(|U_n-U|>\varepsilon)$.`,String.raw`Trên phần bù, $|U_n-U|\le|U_n|+|U|\le2K$, nên phần còn lại không quá $2K P(|U_n-U|>\varepsilon)$.`),b(String.raw`Adding proves $E|U_n-U|\le\varepsilon+2K P(|U_n-U|>\varepsilon)$.`,String.raw`Cộng hai phần cho $E|U_n-U|\le\varepsilon+2K P(|U_n-U|>\varepsilon)$.`),b(String.raw`First fix epsilon and take limsup in n; probability convergence leaves at most epsilon. Since this holds for every epsilon>0 and the expectations are nonnegative, they tend to zero.`,String.raw`Trước hết cố định epsilon rồi lấy limsup theo n; hội tụ xác suất để lại nhiều nhất epsilon. Điều này đúng với mọi epsilon>0 và kỳ vọng không âm, nên chúng tiến về không.`)],
    companions:[
      {prompt:b(String.raw`Let U be uniform on [0,1] and $V_n=1_{[0,1/n]}(U)$ with limit V=0. Use the bounded lemma to show L1 convergence and compute the exact error.`,String.raw`Cho U đều trên [0,1] và $V_n=1_{[0,1/n]}(U)$, giới hạn V=0. Dùng bổ đề bị chặn chứng minh hội tụ L1 và tính sai số chính xác.`),solution:[b(String.raw`The indicators are bounded by 1 and $P(V_n=1)=1/n\to0$, so $V_n\to_P0$.`,String.raw`Các hàm chỉ thị bị chặn bởi 1 và $P(V_n=1)=1/n\to0$, nên $V_n\to_P0$.`),b(String.raw`The bounded lemma applies with K=1, yielding $E|V_n|\to0$.`,String.raw`Bổ đề bị chặn áp dụng với K=1, suy ra $E|V_n|\to0$.`),b(String.raw`Directly, $E|V_n|=1\cdot(1/n)=1/n$, confirming the L1 limit.`,String.raw`Tính trực tiếp, $E|V_n|=1\cdot(1/n)=1/n$, xác nhận giới hạn L1.`)]},
      {prompt:b(String.raw`On a fair four-atom space let $A_n=1_{\{1\}}/n$ and limit zero. Verify probability convergence and use boundedness to obtain the L1 error.`,String.raw`Trên không gian bốn nguyên tử đều, đặt $A_n=1_{\{1\}}/n$ và giới hạn không. Xác minh hội tụ xác suất và dùng tính bị chặn để tìm sai số L1.`),solution:[b(String.raw`For any fixed epsilon>0, once $1/n\le\varepsilon$ the exceedance event is empty, hence $A_n\to_P0$.`,String.raw`Với epsilon>0 cố định, khi $1/n\le\varepsilon$ biến cố vượt rỗng, nên $A_n\to_P0$.`),b(String.raw`All values satisfy $|A_n|\le1$, so the bounded lemma gives $E|A_n|\to0$.`,String.raw`Mọi giá trị thỏa $|A_n|\le1$, nên bổ đề bị chặn cho $E|A_n|\to0$.`),b(String.raw`Exactly, only atom 1 contributes, so $E|A_n|=(1/n)(1/4)=1/(4n)$.`,String.raw`Chính xác, chỉ nguyên tử 1 đóng góp, nên $E|A_n|=(1/n)(1/4)=1/(4n)$.`)]},
      {prompt:b(String.raw`Let $B_n=\min(nU,1)$ on [0,1] with U uniform and limit B=1 almost surely. Prove convergence in probability and compute the L1 error.`,String.raw`Cho $B_n=\min(nU,1)$ trên [0,1] với U đều, giới hạn B=1 h.c. Chứng minh hội tụ xác suất và tính sai số L1.`),solution:[b(String.raw`For U>0, once n≥1/U we have $B_n=1$; U=0 is null.`,String.raw`Với U>0, khi n≥1/U ta có $B_n=1$; U=0 là tập không.`),b(String.raw`Thus $B_n\to1$ almost surely and in probability, with both variables bounded by one.`,String.raw`Vậy $B_n\to1$ hầu chắc và theo xác suất, cả hai biến đều bị chặn bởi một.`),b(String.raw`The error is $(1-nU)_+$; integrating over $0<U<1/n$ gives $E|B_n-1|=\int_0^{1/n}(1-nu)du=1/(2n)\to0$.`,String.raw`Sai số là $(1-nU)_+$; tích phân trên $0<U<1/n$ cho $E|B_n-1|=\int_0^{1/n}(1-nu)du=1/(2n)\to0$.`)]}
    ],
    reviewNote:`The split yields a limsup bound by each fixed epsilon; the correct order is n→∞ first and epsilon↓0 second. Boundedness of both variables is needed for the $2K$ bound.`,
    sourceIds:['p-mit6436']
  },
  'm2-w038-e3': {
    application:b(`A moving spike can vanish in probability while keeping all its expected absolute mass in shrinking sets.`,`Đỉnh nhọn dịch chuyển có thể biến mất theo xác suất nhưng giữ toàn bộ khối lượng kỳ vọng trong các tập co lại.`),
    formula:b(String.raw`$X_n=n1_{(0,1/n)}(U),\ U\sim\mathrm{Unif}(0,1):\quad X_n\to_P0,\quad E|X_n|=1,\quad\{X_n\}\text{ is not UI}.$`,String.raw`$X_n=n1_{(0,1/n)}(U),\ U\sim\mathrm{Unif}(0,1):\quad X_n\to_P0,\quad E|X_n|=1,\quad\{X_n\}\text{ không UI}.$`),
    steps:[b(String.raw`For fixed epsilon>0 and n>epsilon, $\{X_n>\varepsilon\}=(0,1/n)$ up to endpoints, with probability 1/n.`,String.raw`Với epsilon>0 cố định và n>epsilon, $\{X_n>\varepsilon\}=(0,1/n)$ tới các đầu mút, xác suất 1/n.`),b(String.raw`Its expected absolute value is $nP(U<1/n)=n(1/n)=1$, so the L1 norm does not tend to zero.`,String.raw`Kỳ vọng trị tuyệt đối là $nP(U<1/n)=n(1/n)=1$, nên chuẩn L1 không tiến về không.`),b(String.raw`For any K choose n>K; then the entire nonzero spike lies above K and its UI tail expectation equals 1.`,String.raw`Với K bất kỳ chọn n>K; toàn bộ đỉnh khác không nằm trên K và kỳ vọng đuôi UI bằng một.`),b(String.raw`The UI supremum is therefore at least one for every K, so uniform integrability fails.`,String.raw`Vì vậy supremum UI ít nhất bằng một với mọi K, nên khả tích đồng đều thất bại.`)],
    primarySolution:[b(String.raw`For epsilon>0 and n>epsilon, the event $X_n>\varepsilon$ is $(0,1/n)$, so its probability $1/n$ tends to zero.`,String.raw`Với epsilon>0 và n>epsilon, biến cố $X_n>\varepsilon$ là $(0,1/n)$, có xác suất $1/n$ tiến về không.`),b(String.raw`The mean is $E|X_n|=n\cdot(1/n)=1$ for every n, so $X_n$ does not converge to zero in L1.`,String.raw`Kỳ vọng là $E|X_n|=n\cdot(1/n)=1$ với mọi n, nên $X_n$ không hội tụ về không trong L1.`),b(String.raw`For each K choose integer n>K. Then $E[X_n1_{\{X_n>K\}}]=n\cdot(1/n)=1$, disproving UI.`,String.raw`Với mỗi K chọn số nguyên n>K. Khi đó $E[X_n1_{\{X_n>K\}}]=n\cdot(1/n)=1$, bác bỏ UI.`),b(String.raw`Thus the Vitali hypothesis missing here is uniform integrability; bounded first moments alone do not suffice.`,String.raw`Vì vậy giả thiết Vitali thiếu ở đây là khả tích đồng đều; chỉ chặn moment bậc nhất là chưa đủ.`)],
    companions:[
      {prompt:b(String.raw`On [0,1] set $Y_n=\sqrt n\,1_{(0,1/\sqrt n)}(U)$. Check probability convergence, L1 norm, and UI.`,String.raw`Trên [0,1], đặt $Y_n=\sqrt n\,1_{(0,1/\sqrt n)}(U)$. Kiểm tra hội tụ xác suất, chuẩn L1 và UI.`),solution:[b(String.raw`For fixed epsilon and n>epsilon², the exceedance probability is $1/\sqrt n\to0$, so $Y_n\to_P0$.`,String.raw`Với epsilon cố định và n>epsilon², xác suất vượt là $1/\sqrt n\to0$, nên $Y_n\to_P0$.`),b(String.raw`Its L1 norm is $\sqrt n\cdot1/\sqrt n=1$ for every n.`,String.raw`Chuẩn L1 là $\sqrt n\cdot1/\sqrt n=1$ với mọi n.`),b(String.raw`For K choose n>K²; then the tail expectation equals its full mean one, so UI fails.`,String.raw`Với K chọn n>K²; kỳ vọng đuôi bằng toàn bộ trung bình một, nên UI thất bại.`)]},
      {prompt:b(String.raw`On [0,1] let $Z_n=4n1_{(0,1/(4n))}(U)$. Compute its probability limit, L1 norm, and UI-tail supremum.`,String.raw`Trên [0,1], đặt $Z_n=4n1_{(0,1/(4n))}(U)$. Tính giới hạn xác suất, chuẩn L1 và supremum đuôi UI.`),solution:[b(String.raw`For fixed epsilon and n>epsilon/4, $P(Z_n>\varepsilon)=1/(4n)\to0$.`,String.raw`Với epsilon cố định và n>epsilon/4, $P(Z_n>\varepsilon)=1/(4n)\to0$.`),b(String.raw`The mean is $4n\cdot1/(4n)=1$, so its L1 norm stays one.`,String.raw`Kỳ vọng là $4n\cdot1/(4n)=1$, nên chuẩn L1 luôn bằng một.`),b(String.raw`For each K choose n>K/4; then the tail expectation is one and no tail exceeds the full mean, so the supremum is one.`,String.raw`Với K chọn n>K/4; kỳ vọng đuôi bằng một và không đuôi nào vượt trung bình toàn phần, nên supremum bằng một.`)]},
      {prompt:b(String.raw`On [0,1] with Lebesgue measure define $W_n=2^n1_{(0,2^{-n})}(U)$. Show it tends to zero in probability but not L1.`,String.raw`Trên [0,1] với độ đo Lebesgue, đặt $W_n=2^n1_{(0,2^{-n})}(U)$. Chứng minh hội tụ xác suất về không nhưng không hội tụ L1.`),solution:[b(String.raw`For fixed epsilon and n large enough that $2^n>\varepsilon$, $P(W_n>\varepsilon)=2^{-n}\to0$.`,String.raw`Với epsilon cố định và n đủ lớn để $2^n>\varepsilon$, $P(W_n>\varepsilon)=2^{-n}\to0$.`),b(String.raw`Its absolute mean is $2^n2^{-n}=1$ for each n.`,String.raw`Trung bình trị tuyệt đối là $2^n2^{-n}=1$ với mọi n.`),b(String.raw`Choose n with $2^n>K$; the tail expectation is one, so the family is not UI and L1 convergence fails.`,String.raw`Chọn n sao cho $2^n>K$; kỳ vọng đuôi bằng một, nên họ không UI và hội tụ L1 thất bại.`)]}
    ],
    reviewNote:`The moving-spike computations distinguish bounded first moments from UI: each expectation is one, yet tail mass stays one at an index chosen beyond any threshold. Endpoints do not affect Lebesgue probabilities.`,
    sourceIds:['p-mit6436']
  },
  'm2-w038-e4': {
    application:b(`Clip variables into a bounded core and two tails; probability convergence controls the core while UI controls tail mass.`,`Cắt biến thành phần lõi bị chặn và hai đuôi; hội tụ xác suất khống chế phần lõi, còn UI khống chế khối lượng đuôi.`),
    formula:b(String.raw`$X_n,X\text{ real random variables},\quad X_n\to_PX,\ \{X_n\}\text{ UI},\quad\phi_K(x)=\max(-K,\min(x,K)):\quad E|X_n-X|\le E|\phi_K(X_n)-\phi_K(X)|+E|X_n-\phi_K(X_n)|+E|X-\phi_K(X)|.$`,String.raw`$X_n,X\text{ là các biến ngẫu nhiên thực},\quad X_n\to_PX,\ \{X_n\}\text{ UI},\quad\phi_K(x)=\max(-K,\min(x,K)):\quad E|X_n-X|\le E|\phi_K(X_n)-\phi_K(X)|+E|X_n-\phi_K(X_n)|+E|X-\phi_K(X)|.$`),
    steps:[b(String.raw`Clipping is 1-Lipschitz, so $X_n\to_PX$ implies $\phi_K(X_n)\to_P\phi_K(X)$; both clipped variables are bounded by K.`,String.raw`Phép cắt là 1-Lipschitz, nên $X_n\to_PX$ kéo theo $\phi_K(X_n)\to_P\phi_K(X)$; cả hai biến đã cắt đều bị chặn bởi K.`),b(String.raw`The bounded-probability-to-L1 lemma makes the core expectation tend to zero for each fixed K.`,String.raw`Bổ đề bị chặn-xác suất-sang-L1 làm kỳ vọng phần lõi tiến về không với K cố định.`),b(String.raw`The sequence UI makes $E|X_n-\phi_K(X_n)|\le E[|X_n|1_{\{|X_n|>K\}}]$ uniformly small for large K.`,String.raw`Tính UI của dãy làm $E|X_n-\phi_K(X_n)|\le E[|X_n|1_{\{|X_n|>K\}}]$ nhỏ đồng đều khi K lớn.`),b(String.raw`Convergence in probability supplies an a.s.-convergent subsequence; Fatou applied to the l.s.c. tail function gives the same tail bound for X and shows X is integrable.`,String.raw`Hội tụ xác suất cho một dãy con hội tụ h.c.; Fatou áp dụng cho hàm đuôi nửa liên tục dưới cho cùng chặn đuôi của X và cho thấy X khả tích.`),b(String.raw`Let n grow first and then K grow: all three terms vanish in this order, proving $E|X_n-X|\to0$.`,String.raw`Trước hết cho n tăng rồi K tăng: cả ba số hạng triệt tiêu theo thứ tự này, chứng minh $E|X_n-X|\to0$.`)],
    primarySolution:[b(String.raw`Define the clipping map $\phi_K(x)=\max(-K,\min(x,K))$. The triangle inequality splits $E|X_n-X|$ into the clipped-core difference and the two clipping tails.`,String.raw`Định nghĩa phép cắt $\phi_K(x)=\max(-K,\min(x,K))$. Bất đẳng thức tam giác tách $E|X_n-X|$ thành hiệu phần lõi đã cắt và hai đuôi cắt.`),b(String.raw`For fixed K, clipping preserves convergence in probability and bounds both core variables by K, so the bounded lemma gives $E|\phi_K(X_n)-\phi_K(X)|\to0$.`,String.raw`Với K cố định, phép cắt giữ hội tụ xác suất và chặn hai biến lõi bởi K, nên bổ đề bị chặn cho $E|\phi_K(X_n)-\phi_K(X)|\to0$.`),b(String.raw`The sequence-tail term is at most $E[|X_n|1_{\{|X_n|>K\}}]$, uniformly small by UI. To control the limit tail, first select an a.s.-convergent subsequence.`,String.raw`Số hạng đuôi của dãy không quá $E[|X_n|1_{\{|X_n|>K\}}]$, nhỏ đều nhờ UI. Để khống chế đuôi giới hạn, trước hết chọn dãy con hội tụ h.c.`),b(String.raw`Fatou along that subsequence shows X is integrable and $E[|X|1_{\{|X|>K\}}]$ is bounded by the UI tail supremum; this tends to zero as K grows.`,String.raw`Fatou dọc dãy con đó cho thấy X khả tích và $E[|X|1_{\{|X|>K\}}]$ không vượt supremum đuôi UI; chặn này tiến về không khi K tăng.`),b(String.raw`Choose K to make both tails small, then n large to make the core small. Therefore $E|X_n-X|\to0$.`,String.raw`Chọn K để hai đuôi nhỏ, rồi chọn n lớn để phần lõi nhỏ. Do đó $E|X_n-X|\to0$.`)],
    companions:[
      {prompt:b(String.raw`Let U be uniform on [0,1] and $A_n=1_{[0,1/n]}(U)$. Use the truncation argument to explain why $E|A_n|\to0$.`,String.raw`Cho U đều trên [0,1] và $A_n=1_{[0,1/n]}(U)$. Dùng lập luận cắt cụt giải thích vì sao $E|A_n|\to0$.`),solution:[b(String.raw`For U>0 the indicators eventually vanish; the exceptional U=0 is null, so $A_n\to0$ a.s. and in probability.`,String.raw`Với U>0 các chỉ thị cuối cùng triệt tiêu; ngoại lệ U=0 có xác suất không, nên $A_n\to0$ h.c. và theo xác suất.`),b(String.raw`Since $0\le A_n\le1$, the family is UI: its tails vanish for K≥1.`,String.raw`Vì $0\le A_n\le1$, họ là UI: đuôi triệt tiêu khi K≥1.`),b(String.raw`Vitali’s conclusion gives L1 convergence; directly $E|A_n|=1/n$, which confirms it.`,String.raw`Kết luận Vitali cho hội tụ L1; tính trực tiếp $E|A_n|=1/n$ xác nhận điều đó.`)]},
      {prompt:b(String.raw`On [0,1] set $B_n=n1_{(0,1/n^2)}(U)$. Verify probability convergence, UI, and the resulting L1 limit.`,String.raw`Trên [0,1], đặt $B_n=n1_{(0,1/n^2)}(U)$. Xác minh hội tụ xác suất, UI và giới hạn L1 suy ra.`),solution:[b(String.raw`For fixed epsilon and n>epsilon, $P(B_n>\varepsilon)=1/n^2\to0$.`,String.raw`Với epsilon cố định và n>epsilon, $P(B_n>\varepsilon)=1/n^2\to0$.`),b(String.raw`The mean is $E B_n=n/n^2=1/n$. For K fixed, when n>K the tail mean is 1/n, so the supremum over n is bounded by a quantity tending to zero as K grows; terms with n≤K have empty tail.`,String.raw`Kỳ vọng là $E B_n=n/n^2=1/n$. Với K cố định, khi n>K kỳ vọng đuôi là 1/n, nên supremum theo n bị chặn bởi đại lượng tiến về không khi K tăng; các n≤K có đuôi rỗng.`),b(String.raw`Thus the family is UI and Vitali gives $E|B_n|\to0$, consistent with the exact value 1/n.`,String.raw`Vậy họ là UI và Vitali cho $E|B_n|\to0$, phù hợp giá trị chính xác 1/n.`)]},
      {prompt:b(String.raw`For uniform U on [0,1], let $C_n=U^n$. Prove convergence in probability to zero and use boundedness plus Vitali to infer its L1 limit.`,String.raw`Với U đều trên [0,1], đặt $C_n=U^n$. Chứng minh hội tụ xác suất về không và dùng tính bị chặn cùng Vitali suy ra giới hạn L1.`),solution:[b(String.raw`For every u<1, $u^n\to0$; the exceptional point u=1 is null, so convergence is a.s. and hence in probability.`,String.raw`Với mọi u<1, $u^n\to0$; điểm ngoại lệ u=1 có độ đo không, nên hội tụ h.c. và do đó theo xác suất.`),b(String.raw`Since $0\le C_n\le1$, the family is UI by the bounded-family criterion.`,String.raw`Vì $0\le C_n\le1$, tiêu chuẩn họ bị chặn cho thấy họ UI.`),b(String.raw`Vitali gives L1 convergence; direct integration confirms $E|C_n|=\int_0^1u^n\,du=1/(n+1)\to0$.`,String.raw`Vitali cho hội tụ L1; tích phân trực tiếp xác nhận $E|C_n|=\int_0^1u^n\,du=1/(n+1)\to0$.`)]}
    ],
    reviewNote:`The proof sketch needs the standard subsequence principle (probability convergence yields an a.s.-convergent subsequence) and Fatou for the lower-semicontinuous function $x\mapsto|x|1_{\{|x|>K\}}$. UI also bounds first moments, so Fatou first establishes X integrable. Source theorem is presented as a sourced proof sketch, not reproved from the beginning.`,
    sourceIds:['p-mit6436']
  },
  'm2-w038-e5': {
    application:b(`Use a uniformly bounded higher moment to bound the expected first-moment tail beyond K.`,`Dùng moment bậc cao bị chặn đều để chặn kỳ vọng đuôi moment bậc nhất phía ngoài K.`),
    formula:b(String.raw`$X_n\text{ real random variables},\ p>1,\ K>0,\ \sup_nE|X_n|^p\le C<\infty:\quad E[|X_n|1_{\{|X_n|>K\}}]\le E|X_n|^p/K^{p-1}.$`,String.raw`$X_n\text{ là các biến ngẫu nhiên thực},\ p>1,\ K>0,\ \sup_nE|X_n|^p\le C<\infty:\quad E[|X_n|1_{\{|X_n|>K\}}]\le E|X_n|^p/K^{p-1}.$`),
    steps:[b(String.raw`On $\{|X_n|>K\}$ and for K>0, $|X_n|^{p-1}>K^{p-1}$.`,String.raw`Trên $\{|X_n|>K\}$ và K>0, $|X_n|^{p-1}>K^{p-1}$.`),b(String.raw`Rearranging gives $|X_n|\le |X_n|^p/K^{p-1}$ on that event.`,String.raw`Biến đổi được $|X_n|\le |X_n|^p/K^{p-1}$ trên biến cố đó.`),b(String.raw`Multiply by the tail indicator and take expectations to obtain the displayed inequality.`,String.raw`Nhân với hàm chỉ thị đuôi rồi lấy kỳ vọng để được bất đẳng thức đã nêu.`),b(String.raw`Taking the supremum in n bounds every tail by $C/K^{p-1}\to0$ because p−1>0; this is UI.`,String.raw`Lấy supremum theo n chặn mọi đuôi bởi $C/K^{p-1}\to0$ vì p−1>0; đó là UI.`)],
    primarySolution:[b(String.raw`Fix K>0. On the event $|X_n|>K$, divide the inequality $K^{p-1}<|X_n|^{p-1}$ into $|X_n|^p$ to get $|X_n|\le|X_n|^p/K^{p-1}$.`,String.raw`Cố định K>0. Trên biến cố $|X_n|>K$, từ $K^{p-1}<|X_n|^{p-1}$ vào $|X_n|^p$ suy ra $|X_n|\le|X_n|^p/K^{p-1}$.`),b(String.raw`Multiplying by $1_{\{|X_n|>K\}}$ and integrating gives the claimed tail estimate.`,String.raw`Nhân với $1_{\{|X_n|>K\}}$ rồi lấy tích phân cho chặn đuôi cần chứng minh.`),b(String.raw`Now take the supremum over n: it is at most $C/K^{p-1}$.`,String.raw`Lấy supremum theo n: giá trị không quá $C/K^{p-1}$.`),b(String.raw`As K→∞ this bound vanishes since p>1; therefore the family is uniformly integrable.`,String.raw`Khi K→∞ chặn này triệt tiêu vì p>1; do đó họ khả tích đồng đều.`)],
    companions:[
      {prompt:b(String.raw`Let $R_n=\sin(nU)$ for any random U. Use a uniform second-moment bound to show the family is UI.`,String.raw`Cho $R_n=\sin(nU)$ với U ngẫu nhiên bất kỳ. Dùng chặn moment bậc hai đều để chứng minh họ UI.`),solution:[b(String.raw`Since $|R_n|\le1$, $E|R_n|^2\le1$ for every n.`,String.raw`Vì $|R_n|\le1$, ta có $E|R_n|^2\le1$ với mọi n.`),b(String.raw`Apply the moment tail bound with p=2 and C=1: $E[|R_n|1_{\{|R_n|>K\}}]\le1/K$.`,String.raw`Áp dụng chặn đuôi moment với p=2, C=1: $E[|R_n|1_{\{|R_n|>K\}}]\le1/K$.`),b(String.raw`The uniform bound tends to zero, so the family is UI (indeed its tails already vanish for K≥1).`,String.raw`Chặn đều tiến về không, nên họ là UI (thực ra đuôi triệt tiêu khi K≥1).`)]},
      {prompt:b(String.raw`On [0,1] define $S_n=2^n1_{(0,4^{-n})}(U)$. Show the second moments are uniformly bounded and derive a UI tail bound.`,String.raw`Trên [0,1], định nghĩa $S_n=2^n1_{(0,4^{-n})}(U)$. Chứng minh moment bậc hai bị chặn đều và suy ra chặn đuôi UI.`),solution:[b(String.raw`The second moment is $(2^n)^2\,4^{-n}=1$ for every n.`,String.raw`Moment bậc hai là $(2^n)^2\,4^{-n}=1$ với mọi n.`),b(String.raw`For K>0, the p=2 inequality gives $E[|S_n|1_{\{|S_n|>K\}}]\le1/K$.`,String.raw`Với K>0, bất đẳng thức p=2 cho $E[|S_n|1_{\{|S_n|>K\}}]\le1/K$.`),b(String.raw`Taking the supremum preserves this bound, which tends to zero; hence the family is UI.`,String.raw`Lấy supremum vẫn giữ chặn này, tiến về không; vậy họ là UI.`)]},
      {prompt:b(String.raw`For $T_n=3^n1_{(0,9^{-n})}(U)$ on [0,1], calculate the second moments and the tail bound that proves UI.`,String.raw`Với $T_n=3^n1_{(0,9^{-n})}(U)$ trên [0,1], tính moment bậc hai và chặn đuôi chứng minh UI.`),solution:[b(String.raw`Its second moment is $(3^n)^2\,9^{-n}=1$, uniformly in n.`,String.raw`Moment bậc hai là $(3^n)^2\,9^{-n}=1$, đồng đều theo n.`),b(String.raw`On the tail $|T_n|>K$, the moment estimate yields $E[|T_n|1_{\{|T_n|>K\}}]\le1/K$.`,String.raw`Trên đuôi $|T_n|>K$, chặn moment cho $E[|T_n|1_{\{|T_n|>K\}}]\le1/K$.`),b(String.raw`The supremum over n is therefore at most 1/K and tends to zero; this proves UI.`,String.raw`Do đó supremum theo n không quá 1/K và tiến về không; điều này chứng minh UI.`)]}
    ],
    reviewNote:`The pointwise inequality is valid for K>0 and p>1. A uniform pth-moment bound gives an explicit tail rate $C K^{-(p-1)}$, which tends to zero uniformly over the family.`,
    sourceIds:['p-mit6436']
  },

};
